const choice = (prompt, choices, answer, hint, solution) => ({ type: "choice", prompt, choices, answer, hint, solution });
const numeric = (prompt, answer, unit, hint, solution, tolerance = Math.max(Math.abs(answer) * 0.015, 0.01)) => ({ type: "numeric", prompt, answer, unit, tolerance, hint, solution });
const lesson = (title, objectives, notes, workedExample, check, cards, tool = null) => ({ title, objectives, notes, workedExample, check, cards, tool });
const course = (id, code, title, domain, level, credits, prerequisites, summary, outcomes, sources, pathways, modules, capstone) => ({
  id, code, title, domain, level, credits, prerequisites, summary, outcomes, sources, pathways, maturity: "partial",
  modules: modules.map((item, index) => ({ ...item, id: `${id}-${index + 1}` })), capstone,
});

export const courses = [
  course("cell-biology", "BIO 110", "Foundations of Cell and Molecular Biology", "Life sciences", "Year 1", 4, "High-school biology and chemistry", "From molecular structure to cell behavior: build a mechanistic model of how living systems store information, capture energy, and maintain boundaries.", ["Relate macromolecular structure to function.", "Use free-energy and enzyme models to reason about cellular reactions.", "Trace information flow from DNA to phenotype.", "Interpret controls and evidence in a simple molecular experiment."], ["biology", "molecular"], ["biomedical", "geroscience", "tissue"], [
    lesson("Molecular structure and noncovalent forces", ["Distinguish covalent structure from molecular interactions.", "Predict how charge, polarity, and hydrophobicity shape biomolecular assembly."], "Covalent bonds define a molecule's connectivity; hydrogen bonding, electrostatics, van der Waals forces, and the hydrophobic effect help determine its aqueous conformation. Water's high dielectric constant screens charge, but ionic strength changes that screening. A folded protein or assembled membrane is therefore an ensemble of states, not a rigid drawing. Structure-function arguments should identify the interaction that changes and the measurable consequence.", "A phospholipid has a charged or polar headgroup and nonpolar acyl chains. In water, the hydrophobic effect favors bilayers with the tails shielded; it does not require a special covalent bond between lipids.", choice("Which change most directly makes a soluble protein surface less favorable in water?", ["Replacing exposed polar residues with nonpolar residues", "Adding ionizable side chains at neutral pH", "Increasing the number of backbone hydrogen bonds", "Reducing the protein's molecular mass without changing sequence"], 0, "Think about which groups can make favorable interactions with water.", "Nonpolar surface area disrupts water's hydrogen-bond network. Exposing more nonpolar residues raises the free-energy cost of hydration and can promote aggregation or burial in a folded state."), [["Hydrophobic effect", "The tendency of nonpolar surfaces to minimize contact with water; an emergent solvent effect, not a covalent attraction."], ["Ionic strength", "A measure of dissolved ion concentration that affects electrostatic screening in solution."]]),
    lesson("Membranes, transport, and compartmentalization", ["Use electrochemical gradients to determine passive ion movement.", "Separate simple diffusion, facilitated diffusion, and active transport."], "A membrane's permeability depends on solute size, charge, lipid partitioning, and available transport proteins. Passive transport follows an electrochemical potential gradient. For an ion, the chemical term depends on concentration and the electrical term on membrane voltage; the Nernst equation gives the voltage at which those terms balance. Pumps couple an unfavorable transport step to ATP hydrolysis or another favorable gradient. Distinguish transport rate from equilibrium: a channel changes kinetics, not the equilibrium free-energy difference.", "For a neutral solute with equal concentrations on both sides, net diffusive flux is zero even if molecules continue crossing in both directions.", choice("Opening a selective K⁺ channel changes membrane potential. Which statement is most accurate?", ["K⁺ moves until its electrochemical potential difference is zero", "K⁺ must move until both sides have equal K⁺ concentrations", "ATP is consumed by each K⁺ passing through the channel", "The channel changes the total amount of K⁺ in the cell without flux"], 0, "Balance the concentration and electrical contributions; equal concentrations are not required.", "At electrochemical equilibrium the chemical and electrical contributions cancel. An ion channel is passive and does not itself hydrolyze ATP; a concentration difference can remain at the Nernst potential."), [["Electrochemical gradient", "The combined chemical-potential and electrical-potential difference that drives ion movement."], ["Primary active transport", "Transport directly coupled to an energy source such as ATP hydrolysis."]]),
    lesson("Enzymes and cellular energetics", ["Interpret Michaelis-Menten parameters without confusing affinity and rate.", "Relate ΔG to equilibrium and coupling."], "For a simple single-substrate enzyme, v = Vmax[S]/(Km + [S]). Vmax scales with active enzyme concentration; Km is the substrate concentration at half Vmax under the model's assumptions, and is not generally a binding dissociation constant. Catalysts lower activation barriers for forward and reverse reactions without changing ΔG° or the equilibrium constant. Cells drive unfavorable steps by coupling them to favorable reactions, often through ATP or ion gradients; pathway flux also depends on substrate supply, products, and regulation.", "If [S] = Km, the model predicts v = Vmax/2. Doubling enzyme concentration doubles Vmax but leaves Km unchanged in the simple model.", numeric("An enzyme has Vmax = 120 μmol·min⁻¹ and Km = 3 mM. What rate is predicted at [S] = 6 mM? Enter the numerical value in μmol·min⁻¹.", 80, "μmol/min", "Substitute [S] and Km into v = Vmax[S]/(Km + [S]).", "v = 120 × 6/(3 + 6) = 80 μmol·min⁻¹. The substrate concentration is twice Km, so the enzyme is approaching saturation but is not at Vmax."), [["Vmax", "The limiting rate in the Michaelis-Menten model at saturating substrate."], ["Catalyst", "A substance that changes reaction rate by lowering activation barriers without changing the reaction's equilibrium." ]], "enzyme"),
    lesson("Gene expression and experimental logic", ["Trace DNA information through transcription and translation.", "Identify the purpose of positive, negative, and loading controls."], "The central information flow is DNA → RNA → protein, with important exceptions such as reverse transcription. Transcription produces RNA from a template strand; ribosomes decode mRNA codons into a polypeptide. Expression is controlled at multiple stages, including chromatin accessibility, transcription initiation, RNA processing, translation, and protein turnover. An experiment should specify a hypothesis, perturbation, readout, comparison group, and controls. A negative result is interpretable only if the assay's ability to detect a known positive is established.", "In a knockdown experiment, a non-targeting RNA control tests for delivery or off-target effects; a rescue with a perturbation-resistant construct strengthens causal attribution.", choice("A PCR band is absent in a treated sample. Which control most directly shows the PCR itself could detect the target?", ["A positive control containing target template", "A second untreated sample with no template", "A loading dye-only lane", "A replicate of the treated sample"], 0, "Choose a condition expected to produce the signal if the assay works.", "A positive control with target template tests reagent and assay performance. A no-template control is useful for contamination but cannot establish that target amplification is possible."), [["Rescue experiment", "Reintroduction of a functional perturbation-resistant gene or product to test whether a phenotype is caused by a specific loss."], ["Negative control", "A comparison condition lacking the active perturbation, used to estimate background or nonspecific effects."]]),
  ], { prompt: "A membrane-protein mutant reaches the cell surface at normal abundance but abolishes solute flux. Design the shortest evidence chain that distinguishes loss of pore function from loss of protein delivery, and state one remaining alternative explanation.", rubric: ["Uses a direct localization/abundance control", "Measures transport with matched expression and a suitable negative control", "Names an alternative such as altered gating, selectivity, membrane potential, or cell viability"] }),

  course("genetics", "BIO 220", "Genetics & Genomics", "Life sciences", "Year 2", 4, "Foundations of Cell and Molecular Biology", "Move from Mendelian segregation to modern genome-scale inference, keeping recombination, gene regulation, and experimental design in view.", ["Calculate genotype probabilities under explicit assumptions.", "Interpret linkage and recombination data.", "Distinguish association from causal variant evidence.", "Design a controlled gene-expression experiment."], ["biology", "molecular"], ["biomedical", "geroscience"], [
    lesson("Segregation, penetrance, and probability", ["Apply segregation rules to pedigrees.", "Distinguish genotype frequency from phenotype frequency."], "Mendelian models assume defined alleles, segregation, and (for simple ratios) complete penetrance, no viability differences, and independent loci. A Punnett square is a probability model rather than a prediction of each family. Incomplete penetrance means some individuals with a genotype do not show the phenotype; variable expressivity changes severity. Bayes' rule updates risk when family history or a diagnostic test contributes evidence.", "For two heterozygous parents Aa × Aa, the child genotype probabilities are 1/4 AA, 1/2 Aa, and 1/4 aa. A recessive phenotype with full penetrance has probability 1/4 only if both parents are carriers.", choice("Two carrier parents have a recessive condition allele. With full penetrance and independent conceptions, what is the probability their next child is affected?", ["1/2", "1/4", "1/8", "3/4"], 1, "Enumerate the four equally likely allele combinations.", "Aa × Aa yields AA, Aa, Aa, and aa; one of four offspring genotypes is affected aa. The probability for each conception remains 1/4."), [["Penetrance", "The probability that a genotype produces its associated phenotype under specified conditions."], ["Expressivity", "The degree or form in which a genotype-associated phenotype appears among affected individuals."]]),
    lesson("Linkage and recombination mapping", ["Estimate recombination frequency from progeny counts.", "Explain why recombination fraction is a distance proxy with limits."], "Linked loci on the same chromosome are inherited together more often than unlinked loci. Recombination frequency is the fraction of recombinant gametes or progeny in a suitable cross. For short intervals, 1% recombination is approximately 1 centimorgan, but multiple crossovers can make distant loci appear less recombinant; the observable fraction cannot exceed 0.5. Mapping requires clear parental phase and correct identification of parental and recombinant classes.", "If 180 of 1,000 offspring are recombinant in a testcross, r = 0.18 and the loci are approximately 18 cM apart for a short interval.", numeric("In a testcross, 72 of 400 progeny are recombinant. What is the recombination frequency as a percent?", 18, "%", "Divide recombinant progeny by total progeny, then multiply by 100.", "r = 72/400 = 0.18, or 18%. For a short interval, this approximates 18 cM."), [["Testcross", "A cross to a homozygous recessive tester used to reveal the gametes produced by an individual of unknown or heterozygous genotype."], ["Centimorgan", "A mapping unit corresponding approximately to a 1% recombination frequency for short intervals."]]),
    lesson("Gene regulation and causal perturbation", ["Interpret cis-regulatory and trans-acting effects.", "Choose perturbations that distinguish correlation from mechanism."], "A cis-regulatory sequence affects a linked allele on the same DNA molecule; trans-acting factors diffuse and can act on multiple alleles. Reporter assays isolate regulatory fragments but may remove native chromatin context. CRISPR interference can reduce transcription without cutting DNA, while knockout can disrupt coding or regulatory function. Strong causal inference combines a defined perturbation, matched controls, orthogonal readouts, and rescue where feasible.", "If editing a promoter lowers RNA and protein, a promoter-independent cDNA rescue that restores phenotype supports a causal link between reduced gene product and phenotype, while not excluding every downstream effect.", choice("A promoter variant changes expression only from the chromosome carrying it in a heterozygote. This pattern most strongly suggests a:", ["Cis-regulatory effect", "Trans-acting effect", "Mitochondrial inheritance effect", "Random sequencing artifact by definition"], 0, "Ask whether the effect follows one linked allele or alters a diffusible regulator.", "An allele-specific effect confined to the chromosome carrying the variant is the defining pattern of a cis-regulatory effect."), [["Cis-regulatory element", "A DNA sequence that influences expression of a gene on the same DNA molecule."], ["Rescue", "Restoration of a phenotype by reintroducing the implicated function after a perturbation."]]),
    lesson("Genomics, association, and variant interpretation", ["Read an association effect with its uncertainty and population context.", "Separate statistical association from functional causation."], "Genome-wide association studies test many variants, so significance thresholds account for multiple comparisons. A locus may tag a causal variant through linkage disequilibrium; ancestry structure and relatedness can confound association. Effect size, confidence interval, replication, and biological plausibility all matter. Functional follow-up should prioritize a mechanism: tissue-specific expression, chromatin interaction, allele-specific transcription, or perturbation in a relevant model. Predictive association does not by itself establish a treatment target.", "A replicated association with a noncoding SNP narrows a region, not necessarily a gene. Fine-mapping and cell-type-specific perturbation can distinguish plausible regulatory mechanisms.", choice("A significant SNP is associated with a phenotype but lies in a large linkage-disequilibrium block. What is the strongest conclusion?", ["The SNP is the causal variant", "The region contains one or more variants associated with the phenotype", "The nearest gene is the mechanism", "The association proves a treatment will work"], 1, "Association identifies a signal; causal assignment needs additional evidence.", "The associated region is implicated, but correlated variants can share the signal. Fine-mapping, replication, and functional evidence are required before naming a causal variant or gene."), [["Linkage disequilibrium", "Nonrandom association of alleles at different loci in a population."], ["Fine-mapping", "Statistical and functional methods used to narrow an associated region to likely causal variants."]]),
  ], { prompt: "A GWAS locus is associated with slower wound closure. Propose a two-step follow-up that could identify a causal cell type and variant-to-gene mechanism; name one confounder your design must address.", rubric: ["Prioritizes a relevant cell type or tissue using expression/chromatin evidence", "Uses allele-specific or perturbation/rescue evidence to connect variant to gene/function", "Names confounding such as ancestry, cell composition, batch, or linkage disequilibrium"] }),

  course("physiology", "BIO 230", "Human Physiology for Engineers", "Life sciences", "Year 2", 4, "Cell biology; Physics: Mechanics; calculus recommended", "Quantitative homeostasis across excitable, cardiovascular, respiratory, renal, and endocrine systems, with emphasis on feedback and transport.", ["Use mass and energy balance to describe homeostasis.", "Interpret pressure-flow and resistance relationships.", "Connect membrane transport to organ-level function.", "Predict responses to controlled perturbations."], ["biology", "transport"], ["biomedical", "geroscience", "tissue"], [
    lesson("Homeostasis and feedback", ["Represent a regulated variable, sensor, controller, and effector.", "Distinguish negative from positive feedback."], "A homeostatic system regulates a variable around a reference state using sensors, integrators, and effectors. Negative feedback opposes deviations; positive feedback amplifies them and usually requires a terminating event. A simple balance dX/dt = input − output helps identify steady state and response time. Regulation can preserve a variable while changing the control effort, so an apparently normal value can hide compensation.", "If a circulating solute enters at 5 μmol/min and is cleared with first-order rate constant 0.1 min⁻¹, the steady concentration in a well-mixed 1 L compartment is 50 μmol/L.", numeric("A 2 L well-mixed compartment receives solute at 12 μmol/min. First-order clearance is k = 0.3 min⁻¹. What is the steady concentration in μmol/L?", 20, "μmol/L", "At steady state, input = k·V·C. Solve for C.", "C* = input/(kV) = 12/(0.3×2) = 20 μmol/L."), [["Negative feedback", "Control in which a response reduces the deviation that elicited it."], ["Steady state", "A condition where state variables are constant in time because net rates of change are zero; flows may continue."]]),
    lesson("Excitable cells and electrophysiology", ["Interpret membrane voltage as an electrical state variable.", "Relate ionic conductance to current and reversal potential."], "The membrane behaves approximately as a capacitor in parallel with ion-selective conductances. Ionic current follows Iᵢ = gᵢ(Vm − Eᵢ), with sign determined by the chosen current convention. Opening a conductance drives voltage toward that ion's reversal potential. Action potentials arise from voltage- and time-dependent conductance changes; refractory behavior and propagation depend on channel kinetics and cable properties, not simply on a fixed voltage threshold.", "If Vm = −60 mV, EK = −90 mV, and gK = 2 nS, then outward-positive IK = 2 nS × 30 mV = 60 pA.", numeric("A membrane has gNa = 4 nS, Vm = −50 mV, and ENa = +50 mV. Using I = g(Vm − E), what is INa in pA?", -400, "pA", "The driving force is −50 − (+50) = −100 mV; 1 nS·mV = 1 pA.", "INa = 4 nS × (−100 mV) = −400 pA under this convention; the negative sign indicates inward positive charge."), [["Reversal potential", "The membrane voltage at which the net current carried by a particular ion is zero."], ["Conductance", "A measure of how readily charge flows; in I = g(V − E), it scales current for a given driving force."]]),
    lesson("Cardiovascular and respiratory transport", ["Use pressure-flow resistance analogies with stated assumptions.", "Distinguish ventilation, perfusion, and diffusion limitation."], "Bulk flow moves blood or air through conduits; diffusion moves solutes down concentration gradients across exchange surfaces. For laminar flow in a cylindrical tube, Poiseuille resistance scales as R = 8μL/(πr⁴), so small radius changes strongly affect flow at fixed pressure drop. Gas exchange depends on surface area, barrier thickness, solubility, and perfusion. Ventilation-perfusion mismatch can limit oxygen transfer even when total ventilation is adequate.", "Doubling vessel radius at fixed length and viscosity lowers ideal Poiseuille resistance by a factor of 16; real vessels also change tone and geometry.", choice("For ideal laminar flow in a rigid tube, doubling the radius at fixed pressure drop changes volumetric flow by a factor of:", ["2", "4", "8", "16"], 3, "Poiseuille flow depends on the fourth power of radius.", "Q ∝ r⁴, so doubling r multiplies flow by 2⁴ = 16 under the model assumptions."), [["Perfusion", "Blood flow through a tissue's microvasculature."], ["Ventilation-perfusion mismatch", "A spatial imbalance between air reaching alveoli and blood reaching their capillaries."]]),
    lesson("Renal, endocrine, and integrated regulation", ["Use clearance and balance concepts to interpret kidney function.", "Predict how hormonal feedback changes transport or set points."], "Renal function combines filtration, reabsorption, secretion, and excretion. Clearance Cx = Ux·V̇/Px expresses the plasma volume cleared of a substance per unit time, subject to steady-state and sampling assumptions. Endocrine signals act through receptor occupancy and downstream transduction; hormone concentration alone does not equal tissue response. Integrating organ systems requires tracing the manipulated variable, compensatory response, and any cost of compensation.", "If urinary concentration is 50 mg/L, urine flow is 1 mL/min, and plasma concentration is 2 mg/L, clearance is 25 mL/min.", numeric("A solute has urine concentration 24 mg/L, urine flow 1.5 mL/min, and plasma concentration 3 mg/L. Compute clearance in mL/min.", 12, "mL/min", "Use Cx = Ux·V̇/Px.", "Cx = 24 × 1.5 / 3 = 12 mL/min."), [["Clearance", "The virtual volume of plasma cleared of a substance per unit time, calculated from urine and plasma concentrations."], ["Compensation", "A response that helps maintain a regulated variable while potentially changing system load or reserve."]]),
  ], { prompt: "A patient has normal resting arterial pressure but reduced renal perfusion and elevated sympathetic activity. Explain how a compensated value can coexist with impaired reserve, and propose one measurement that tests your explanation.", rubric: ["Identifies a feedback response that preserves pressure", "Explains a cost or reduced reserve under challenge", "Proposes a perturbation or independent readout such as orthostatic response, renal flow, or hormone level"] }),

  course("general-chemistry-1", "CHEM 101", "General Chemistry I", "Chemistry", "Year 1", 4, "Algebra; high-school chemistry recommended", "Chemical structure, stoichiometry, thermochemistry, and equilibrium developed with explicit attention to units, assumptions, and molecular-scale interpretation.", ["Balance reactions and quantify limiting reagents.", "Relate bonding and molecular geometry to properties.", "Use energy conservation and equilibrium models.", "Check dimensions and significant figures in calculations."], ["chemistry"], ["biomedical", "robotics", "geroscience", "tissue"], [
    lesson("Atoms, bonding, and molecular shape", ["Connect electron configuration to periodic trends.", "Use Lewis structures and VSEPR as models with defined limits."], "Electron configuration organizes valence behavior; effective nuclear charge, shielding, and subshell occupancy help explain periodic trends. Lewis structures track valence electrons and formal charge. VSEPR predicts approximate molecular geometry from electron domains, while molecular orbital ideas explain bond order and magnetism more deeply. Geometry and polarity influence solubility, intermolecular forces, and molecular recognition, but shape predictions should not be mistaken for full quantum descriptions.", "For water, two bonds and two lone pairs around oxygen give a bent molecular shape. Polar O–H bonds and the bent geometry produce a net dipole.", choice("Which species has a trigonal planar molecular geometry at its central atom?", ["CH₄", "NH₃", "BF₃", "H₂O"], 2, "Count bonding domains and lone pairs around the central atom.", "BF₃ has three bonding domains and no lone pairs on boron, giving a trigonal planar geometry. CH₄ is tetrahedral; NH₃ is trigonal pyramidal; H₂O is bent."), [["Formal charge", "A bookkeeping assignment: valence electrons minus nonbonding electrons minus half the bonding electrons."], ["Dipole moment", "A vector measure of separated positive and negative charge in a bond or molecule."]]),
    lesson("Stoichiometry and solution concentration", ["Balance chemical equations before converting amounts.", "Use limiting-reagent and dilution relationships with units."], "A balanced equation conserves atoms and charge. Stoichiometric coefficients relate moles, not masses or volumes directly; use molar mass or concentration to convert. The limiting reagent sets maximum product. In dilute solutions, molarity is moles of solute per liter of solution. During a dilution with no reaction or loss, moles of solute are conserved, so C₁V₁ = C₂V₂ when units are consistent.", "To prepare 100 mL of 0.20 M NaCl from a 2.0 M stock, use V₁ = C₂V₂/C₁ = 10 mL and dilute to a final volume of 100 mL.", numeric("What volume of 1.5 M stock is needed to prepare 300 mL of 0.10 M solution? Enter mL.", 20, "mL", "Apply C₁V₁ = C₂V₂, keeping both volumes in the same unit.", "V₁ = (0.10 M × 300 mL)/(1.5 M) = 20 mL; bring to a final volume of 300 mL.", 0.2), [["Limiting reagent", "The reactant consumed first under the balanced stoichiometric ratio; it limits theoretical product."], ["Molarity", "Moles of solute divided by final solution volume in liters."]], "dilution"),
    lesson("Thermochemistry and state functions", ["Use the first law with a clear sign convention.", "Estimate reaction enthalpy from formation enthalpies."], "The first law is ΔU = q + w when work done on the system is positive. Enthalpy H = U + PV is useful for constant-pressure processes; ΔH is approximately the heat transferred at constant pressure when only PV work occurs. Standard reaction enthalpy follows ΔH°rxn = ΣνΔH°f(products) − ΣνΔH°f(reactants). A state function depends on initial and final states, not path, so Hess's law allows reaction steps to be added algebraically.", "If a reaction's products have a total formation enthalpy of −500 kJ/mol and reactants total −300 kJ/mol, ΔH°rxn = −200 kJ/mol.", numeric("For a reaction, ΣνΔH°f(products) = −620 kJ/mol and ΣνΔH°f(reactants) = −410 kJ/mol. Find ΔH°rxn in kJ/mol.", -210, "kJ/mol", "Subtract reactant formation enthalpies from product formation enthalpies.", "ΔH°rxn = −620 − (−410) = −210 kJ/mol, exothermic under the standard-state convention."), [["State function", "A property whose change depends only on initial and final states, not the path taken."], ["Hess's law", "Reaction enthalpies add when chemical equations are added, because enthalpy is a state function."]]),
    lesson("Chemical equilibrium", ["Write a reaction quotient from a balanced equation.", "Predict direction of net change by comparing Q and K."], "At equilibrium, forward and reverse rates are equal, not necessarily zero. For aA + bB ⇌ cC + dD, Q = [C]^c[D]^d/([A]^a[B]^b), omitting pure solids and liquids. If Q < K, net reaction proceeds toward products; if Q > K, toward reactants. K changes with temperature, while concentration or pressure perturbations change Q and the equilibrium composition. Equilibrium constants are dimensionless when written with activities; concentration forms are approximations for sufficiently dilute solutions.", "Adding reactant makes Q smaller while K remains fixed at constant temperature; the system then shifts toward products until Q = K.", choice("At a fixed temperature, a reaction mixture has Q = 0.2 and K = 5. What is the direction of net reaction?", ["Toward reactants", "Toward products", "Already at equilibrium", "Cannot be inferred without the reaction enthalpy"], 1, "Compare Q and K at the same temperature.", "Because Q < K, the mixture has too little product relative to equilibrium and net forward reaction proceeds toward products."), [["Reaction quotient Q", "The mass-action expression evaluated at the current composition."], ["Equilibrium constant K", "The value of the reaction quotient at equilibrium for a specified temperature and standard-state convention."]]),
  ], { prompt: "A 0.50 L buffer-preparation vessel contains 0.050 mol weak acid and 0.030 mol conjugate base. After adding a small amount of strong acid, pH falls more than predicted. Give two chemical or experimental causes and one measurement that distinguishes them.", rubric: ["Accounts for stoichiometric neutralization of conjugate base", "Names a nonideal cause such as ionic-strength/activity effects, wrong pKa/temperature, or concentration error", "Proposes a discriminating calibration or composition measurement"] }),

  course("general-chemistry-2", "CHEM 102", "General Chemistry II", "Chemistry", "Year 1", 4, "General Chemistry I", "Kinetics, acid-base systems, electrochemistry, and coordination chemistry connected to buffers, redox biology, and metal-dependent biomolecules.", ["Solve equilibrium and buffer problems.", "Interpret rate laws and activation energy.", "Relate redox potential to electron-transfer direction.", "Explain coordination geometry and ligand effects."], ["chemistry", "biochemistry"], ["biomedical", "geroscience", "tissue"], [
    lesson("Acid-base equilibria and buffers", ["Use Ka, pKa, and mass balance to reason about weak acids.", "Estimate buffer pH with Henderson-Hasselbalch when assumptions hold."], "For HA ⇌ H⁺ + A⁻, Ka = [H⁺][A⁻]/[HA]. In a buffer with appreciable amounts of both forms, pH = pKa + log₁₀([A⁻]/[HA]) approximates the equilibrium relation. The approximation is most useful when concentrations are well above water autoionization and activity effects are modest. Strong acid or base first reacts stoichiometrically with buffer components; update moles before applying the ratio. Buffer capacity depends on total concentration and is largest near pH = pKa.", "At pH = pKa, [A⁻]/[HA] = 1. Adding 1 mmol HCl to a buffer consumes approximately 1 mmol A⁻ and forms 1 mmol HA before recalculating pH.", numeric("A buffer has pKa = 7.2 and [A⁻]/[HA] = 10. What is its approximate pH?", 8.2, "pH", "Use pH = pKa + log₁₀(base/acid).", "pH = 7.2 + log₁₀(10) = 8.2."), [["Buffer capacity", "The amount of strong acid or base a solution can absorb per pH change."], ["pKa", "−log₁₀ Ka; a useful reference point where conjugate acid and base concentrations are equal in an ideal buffer."]], "buffer"),
    lesson("Kinetics and reaction mechanisms", ["Infer reaction order from rate data.", "Relate temperature to rate constants through Arrhenius behavior."], "A rate law is determined experimentally and is not generally inferred from the balanced overall equation. For an elementary step, exponents reflect molecularity, but mechanisms can contain intermediates and rate-limiting steps. The integrated first-order law is ln([A]t/[A]0) = −kt, with half-life ln 2/k. Arrhenius behavior k = A exp(−Ea/RT) predicts faster rates at higher temperature for positive activation energy, while catalysts provide an alternate pathway with lower Ea.", "A first-order process with k = 0.20 min⁻¹ has half-life 0.693/0.20 = 3.47 min.", numeric("A first-order reaction has k = 0.35 min⁻¹. What is its half-life in minutes?", 1.98, "min", "Use t½ = ln 2/k.", "t½ = 0.693/0.35 = 1.98 min."), [["Rate-determining step", "A mechanistic step that constrains the overall reaction rate under specified conditions."], ["Activation energy Ea", "The energy barrier parameter that governs the temperature sensitivity of a rate constant in Arrhenius behavior."]]),
    lesson("Redox and electrochemical cells", ["Balance oxidation-reduction reactions by electron accounting.", "Use cell potential to predict spontaneity under specified conditions."], "Oxidation loses electrons and reduction gains them. Standard reduction potentials are intensive properties and are not multiplied by stoichiometric coefficients. For a galvanic cell under standard conditions, E°cell = E°cathode − E°anode and ΔG° = −nFE°cell. Under nonstandard conditions, the Nernst equation adjusts potential for activities. Biological redox couples depend on pH, concentrations, compartmentation, and coupling to other reactions.", "If E°cathode = +0.80 V and E°anode = −0.20 V, E°cell = +1.00 V; for n > 0, ΔG° is negative.", numeric("A cell transfers n = 2 electrons and has E°cell = 0.30 V. Using F = 96,485 C/mol, calculate ΔG° in kJ/mol.", -57.9, "kJ/mol", "Use ΔG° = −nFE°, then convert joules to kilojoules.", "ΔG° = −2 × 96,485 × 0.30 J/mol = −57,891 J/mol ≈ −57.9 kJ/mol."), [["Cathode", "The electrode at which reduction occurs."], ["Nernst equation", "A relation that adjusts electrode potential for nonstandard activities and temperature."]]),
    lesson("Coordination chemistry and biologically relevant metals", ["Identify the metal center, donor atoms, and coordination number.", "Explain how ligands tune geometry and redox behavior."], "Transition-metal ions bind ligands through donor atoms, forming coordination complexes. Coordination number and ligand-field effects influence geometry, color, magnetic properties, and redox potential. In proteins, the local environment can tune reactivity far beyond what the free metal ion exhibits. Metal speciation also depends on pH and competing ligands; total elemental concentration is not the same as bioavailable or catalytically active concentration.", "A heme iron can bind axial ligands and reversibly coordinate O₂; protein residues tune oxygen affinity and protect the metal center.", choice("Why can the same metal ion show different redox behavior in two proteins?", ["The protein environment changes ligand field, electrostatics, and access to substrates", "A protein makes conservation of charge unnecessary", "All metal ions have a fixed potential independent of coordination", "Proteins eliminate thermal motion"], 0, "Consider how the coordination sphere changes the energetic cost of each oxidation state.", "Ligands and local electrostatics stabilize oxidation states differently and control substrate access, thereby tuning redox potential and reaction kinetics."), [["Coordination number", "The number of donor atoms directly bonded to a central metal in a complex."], ["Bioavailability", "The fraction of an element present in a form accessible for uptake or biochemical use."]]),
  ], { prompt: "An enzyme assay shows a metal-dependent rate increase. Outline a control set that separates metal cofactor rescue from nonspecific ionic-strength or precipitation effects.", rubric: ["Uses metal-depleted/apo-enzyme and defined metal add-back", "Includes a matched inert-salt or ionic-strength control", "Checks soluble metal/enzyme or turbidity and includes activity blanks"] }),

  course("organic-chemistry", "CHEM 231", "Organic Chemistry I for Life Sciences", "Chemistry", "Year 2", 4, "General Chemistry I and II", "Structure, stereochemistry, substitution, elimination, and carbonyl chemistry taught through mechanism and reactivity rather than reaction memorization.", ["Draw valid resonance contributors and predict nucleophile/electrophile roles.", "Use substrate, nucleophile, solvent, and leaving group to distinguish mechanisms.", "Track stereochemistry and regiochemistry.", "Relate functional-group reactivity to biomolecular synthesis and degradation."], ["organic", "chemistry"], ["biomedical", "geroscience", "tissue"], [
    lesson("Structure, resonance, and acid-base reactivity", ["Rank acidity using conjugate-base stabilization.", "Use resonance without moving atoms or violating valence."], "Organic reactivity begins with electron distribution. Resonance contributors move electrons, not nuclei; valid contributors preserve sigma-bond connectivity and total charge. Acidity depends on the stability of the conjugate base, shaped by atom identity, resonance, induction, hybridization, and solvation. Curved arrows start at electron pairs or bonds and end where electrons move. Explicit charges and complete electron accounting prevent common mechanism errors.", "A carboxylate conjugate base distributes negative charge over two oxygens, making a carboxylic acid more acidic than a typical alcohol whose alkoxide charge is localized.", choice("Which conjugate base is most stabilized by resonance?", ["CH₃O⁻", "CH₃CO₂⁻", "CH₃CH₂⁻", "NH₂⁻"], 1, "Look for equivalent or near-equivalent atoms that can share charge through π bonding.", "The acetate ion delocalizes negative charge over two oxygen atoms. The other listed anions lack comparable resonance stabilization."), [["Conjugate base", "The species formed when an acid donates a proton."], ["Resonance", "A representation of electron delocalization using multiple Lewis contributors with unchanged atomic positions."]]),
    lesson("Substitution mechanisms: SN1 and SN2", ["Predict how substrate structure and solvent affect substitution.", "Connect mechanism to stereochemical outcome and rate law."], "SN2 is a concerted backside displacement; its rate depends on both substrate and nucleophile, and a stereogenic center inverts configuration. SN1 proceeds through a carbocation intermediate; the rate-limiting ionization depends mainly on substrate, and rearrangements or partial racemization may occur. Strong nucleophiles, steric accessibility, leaving-group ability, and solvent all matter. Biological nucleophilic substitutions are often organized by enzyme binding and proton transfer, so solution heuristics need context.", "A primary alkyl halide with a strong nucleophile in a polar aprotic solvent favors SN2; a tertiary substrate blocks backside attack and may favor ionization when a stable carbocation can form.", choice("A tertiary alkyl halide in water undergoes substitution. Which pathway is generally more plausible?", ["SN2, because the tertiary center is unhindered", "SN1, because ionization can form a stabilized carbocation", "Neither pathway can occur in a protic solvent", "A radical chain is required"], 1, "Tertiary substitution centers are strongly sterically hindered for backside attack.", "SN1 is generally favored for a tertiary center in a polar protic solvent because carbocation formation is stabilized and SN2 is sterically hindered. The actual pathway depends on the full substrate and conditions."), [["SN2", "A concerted bimolecular nucleophilic substitution with backside attack and inversion at a stereogenic center."], ["Leaving group", "A substituent that departs with the bonding electron pair during a reaction."]]),
    lesson("Elimination, alkenes, and stereochemical control", ["Distinguish E1 and E2 pathways.", "Predict alkene products while stating regioselectivity assumptions."], "E2 elimination is concerted and requires an antiperiplanar arrangement of the C–H and C–leaving-group bonds. E1 passes through a carbocation and can rearrange. Base strength, substrate substitution, solvent, and temperature influence competition with substitution. Zaitsev product is common when the more substituted alkene is more stable, while bulky bases or conformational constraints can alter selectivity. Product prediction should report stereochemistry when geometry constrains the elimination.", "In a cyclohexane chair, E2 requires a trans-diaxial beta hydrogen and leaving group; ring flip can expose the reactive conformation.", choice("Which geometric arrangement is required for a typical concerted E2 elimination?", ["Anti-periplanar C–H and C–leaving-group bonds", "Any arrangement because the carbocation rotates", "A tetrahedral carbon with no beta hydrogen", "An aromatic ring with all sigma bonds fixed"], 0, "E2 forms the π bond as the C–H and C–leaving-group bonds break together.", "The required orbital alignment is usually anti-periplanar; in a cyclohexane chair this is trans-diaxial."), [["Antiperiplanar", "A dihedral angle near 180° between bonds that align for concerted elimination."], ["Regioselectivity", "Preference for forming one constitutional isomer over another." ]]),
    lesson("Carbonyl chemistry and acyl transfer", ["Explain why carbonyl carbon is electrophilic.", "Predict addition versus substitution from the carbonyl derivative."], "The polarized C=O bond leaves carbon electrophilic and oxygen nucleophilic. Aldehydes and ketones usually undergo nucleophilic addition. Carboxylic-acid derivatives can undergo nucleophilic acyl substitution because a leaving group can depart after tetrahedral-intermediate formation; leaving-group ability and resonance donation govern relative reactivity. In biochemistry, acyl transfer is often driven by activation, enzyme catalysis, or coupling to nucleotide triphosphate hydrolysis rather than by an unusually strong naked nucleophile.", "An ester plus hydroxide forms a tetrahedral intermediate; collapse expels an alkoxide, followed by proton transfer to give a carboxylate under basic conditions.", choice("Why are acid chlorides generally more reactive toward nucleophilic acyl substitution than amides?", ["Chloride is a better leaving group and donates less by resonance", "Amide carbonyl carbon is more electrophilic", "Amides have no carbonyl resonance", "Chloride prevents nucleophilic attack"], 0, "Compare leaving-group basicity and resonance donation into the carbonyl.", "Chloride is a weaker base and better leaving group than an amide anion, while nitrogen donates strongly by resonance and reduces amide carbonyl electrophilicity."), [["Nucleophilic acyl substitution", "Addition to a carbonyl followed by elimination of a leaving group at an acyl carbon."], ["Tetrahedral intermediate", "The intermediate formed after nucleophilic addition converts trigonal-planar carbonyl carbon to tetrahedral geometry."]]),
  ], { prompt: "A proposed synthesis forms an amide from a carboxylic acid and amine in water at neutral pH. Explain why this is not a sufficient mechanism and name one activation strategy plus a control for product identity.", rubric: ["Recognizes poor leaving-group/acid-base competition in unactivated condensation", "Proposes activation such as an activated ester, carbodiimide, or acyl enzyme", "Names an analytical confirmation such as LC-MS, NMR, or a diagnostic hydrolysis comparison"] }),

  course("biochemistry", "BIOC 301", "Biochemistry I: Proteins, Enzymes & Metabolism", "Biochemistry", "Year 2", 4, "General Chemistry II; Organic Chemistry I recommended", "A mechanistic and quantitative introduction to protein structure, enzyme kinetics, thermodynamics, central metabolism, and pathway regulation.", ["Interpret protein sequence, structure, and binding models.", "Quantify enzyme saturation and inhibition.", "Track carbon, electrons, and energy through central metabolism.", "Explain pathway control through multiple regulatory layers."], ["biochemistry", "biology"], ["biomedical", "geroscience", "tissue"], [
    lesson("Protein structure and molecular recognition", ["Describe primary through quaternary structure.", "Distinguish binding affinity, specificity, and cooperativity."], "Primary sequence constrains local structure and folding but does not uniquely specify a single rigid state in every environment. Secondary and tertiary structure emerge from backbone geometry, hydrophobic packing, hydrogen bonding, electrostatics, and solvent. Ligand binding is governed by ΔG and can involve conformational selection or induced fit. The dissociation constant Kd reports equilibrium occupancy in a simple 1:1 model; a low Kd indicates tight binding but not necessarily fast association or catalytic efficiency.", "For a 1:1 interaction at free ligand concentration [L] = Kd, fractional occupancy θ = [L]/(Kd + [L]) = 0.5.", numeric("A protein has Kd = 4 μM. In a simple 1:1 model, what fraction of sites is occupied at free ligand concentration 12 μM? Enter a fraction from 0 to 1.", 0.75, "fraction", "Use θ = [L]/(Kd + [L]).", "θ = 12/(4 + 12) = 0.75, or 75% occupancy under the simple equilibrium model."), [["Dissociation constant Kd", "At equilibrium in a simple binding model, the ligand concentration associated with half occupancy."], ["Cooperativity", "A change in one binding event's effect on the affinity of additional sites in a multisite system."]]),
    lesson("Enzyme mechanisms and inhibition", ["Distinguish competitive and noncompetitive model signatures.", "Use catalytic efficiency and model assumptions carefully."], "Enzymes stabilize transition states and use acid-base, covalent, metal-ion, or proximity/orientation strategies. In the simplest Michaelis-Menten model, competitive inhibition increases apparent Km without changing Vmax; pure noncompetitive inhibition lowers Vmax with unchanged Km. Real inhibitors may be mixed, tight-binding, time-dependent, or allosteric, so model fit and assay conditions matter. kcat/Km is a useful low-substrate measure of catalytic efficiency, bounded by diffusion for many enzymes.", "If competitive inhibitor raises apparent Km from 2 to 8 mM while Vmax remains 100 μmol/min, sufficiently high substrate can still approach the same Vmax.", choice("In a simple competitive-inhibition model, what happens as inhibitor concentration increases?", ["Apparent Km increases; Vmax is unchanged", "Km decreases; Vmax increases", "Both Km and Vmax decrease by the same factor", "The enzyme's equilibrium constant changes"], 0, "The inhibitor competes with substrate for binding but can be outcompeted at high substrate.", "Competitive inhibition raises apparent Km while leaving Vmax unchanged in the ideal model, because saturating substrate can outcompete inhibitor."), [["kcat", "Turnover number: catalytic cycles per enzyme molecule per unit time at substrate saturation."], ["Competitive inhibition", "Inhibition that raises apparent Km in the simple model while preserving Vmax at saturating substrate."]]),
    lesson("Bioenergetics and central carbon metabolism", ["Track oxidation state and carbon fate through glycolysis and respiration.", "Relate redox carriers and proton motive force to ATP synthesis."], "Glycolysis converts glucose to pyruvate while producing ATP and NADH. Under aerobic conditions, pyruvate oxidation and the citric-acid cycle generate reduced cofactors; electron transport transfers electrons to oxygen and pumps protons. ATP synthase couples proton return to phosphorylation. The overall ATP yield per glucose depends on shuttle systems, leak, cell type, and accounting convention. Carbon and electron balances provide a more reliable framework than memorizing one universal ATP number.", "Net glycolysis produces 2 ATP and 2 NADH per glucose. If a preparation yields 3 ATP per cytosolic NADH via its chosen shuttle, glycolytic reducing equivalents contribute 6 ATP equivalents in that accounting scheme.", numeric("A glycolytic pathway processes 5 mol glucose. How many mol of net ATP are formed directly in glycolysis?", 10, "mol ATP", "Glycolysis nets 2 ATP per glucose molecule.", "5 mol glucose × 2 mol ATP/mol glucose = 10 mol ATP; this excludes downstream oxidative phosphorylation."), [["Proton motive force", "An electrochemical proton gradient across a membrane that can power transport and ATP synthesis."], ["Redox carrier", "A molecule such as NAD⁺/NADH that transfers electrons between metabolic reactions."]]),
    lesson("Pathway regulation and metabolic integration", ["Identify control at substrate supply, allostery, covalent modification, and expression.", "Predict how perturbing one pathway affects connected fluxes."], "Metabolic flux is distributed across pathways and is not controlled by one universal rate-limiting enzyme. Regulation occurs through substrate availability, allosteric effectors, phosphorylation, enzyme abundance, compartmentation, and hormonal signals. Mass balance constrains steady-state intermediates, while isotope tracing can reveal carbon flow through parallel pathways. A metabolite pool size alone does not reveal flux: it can rise because production increased or consumption fell.", "If a labeled-carbon pool stays constant while labeled product appearance slows, both production and consumption may have changed; isotope time courses help separate those rates.", choice("A metabolite concentration is unchanged after a perturbation. What can be concluded about pathway flux?", ["Flux is unchanged", "Flux is zero", "The steady pool size alone does not determine flux", "All upstream and downstream enzymes are unchanged"], 2, "A pool is a state; fluxes are rates in and out that can change together.", "A constant concentration only shows that net accumulation is near zero at that time. Production and consumption can both increase or decrease while the pool stays constant."), [["Metabolic flux", "The rate at which material flows through a reaction or pathway."], ["Isotope tracing", "Use of labeled atoms to follow molecular transformations and estimate pathway flow."]]),
  ], { prompt: "A mitochondrial inhibitor reduces ATP and increases lactate. Propose a carbon/electron-flow explanation and one experiment that distinguishes impaired oxidative phosphorylation from a primary glycolytic defect.", rubric: ["Connects electron transport inhibition to NADH reoxidation and proton motive force/ATP", "Explains increased glycolytic dependence and lactate as a redox outlet", "Chooses a discriminating measurement such as oxygen consumption, NADH/NAD⁺, isotope tracing, or rescue with an electron acceptor"] }),

  course("calculus-1", "MATH 151", "Calculus I: Differential and Integral Calculus", "Mathematics", "Year 1", 4, "Algebra, functions, trigonometry", "Limits, derivatives, and integrals as tools for local change and accumulated quantities, with modeling examples from growth, transport, and mechanics.", ["Evaluate limits and justify continuity claims.", "Differentiate composite and implicit functions.", "Use derivatives to analyze and optimize models.", "Interpret definite integrals as accumulated change."], ["calculus", "engineeringMath"], ["biomedical", "robotics", "geroscience", "tissue"], [
    lesson("Limits, continuity, and approximation", ["Evaluate limits using algebraic and graphical reasoning.", "Use a local linear approximation and estimate its domain of validity."], "A limit describes the value approached as an input approaches a point; it need not equal the function's value there. Continuity at a requires the function to be defined at a, the limit to exist, and the two values to agree. The derivative later formalizes the best local linear approximation. When applying a model near a reference state, quantify the neglected higher-order terms and do not extrapolate a local approximation far outside that state.", "For f(x) = x² near x = 3, the linear approximation is f(3+h) ≈ 9 + 6h; at h = 0.1 the approximation is 9.6 versus the exact 9.61.", numeric("For f(x) = x², what is f′(3)?", 6, "", "Use the limit definition or the power rule after establishing the derivative.", "f′(x)=2x, so f′(3)=6. It is the local rate of change of the output per unit input."), [["Limit", "The value a function approaches as its input approaches a specified point."], ["Linearization", "A first-order local approximation f(a+h) ≈ f(a) + f′(a)h."]]),
    lesson("Derivative rules and chain rule", ["Differentiate products, quotients, and nested functions.", "Keep variables and units attached to a model's rate of change."], "The derivative is a local slope and instantaneous rate. Product and quotient rules handle composed arithmetic; the chain rule handles nested dependence: d/dx f(g(x)) = f′(g(x))g′(x). In a physical model, derivatives inherit units: if position is meters and time seconds, velocity has units m/s. The chain rule is especially important in biological models where a measured output depends on a hidden state that itself depends on time or dose.", "If response R(c) = 100c/(2+c) and concentration c(t) changes in time, dR/dt = (200/(2+c)²)·dc/dt.", numeric("If y = (3x + 1)⁴, compute dy/dx at x = 1.", 768, "", "Apply the chain rule: 4(3x+1)³·3, then set x = 1.", "dy/dx = 12(3x+1)³. At x=1 this is 12×4³ = 768."), [["Chain rule", "The derivative rule for nested functions: d f(g(x))/dx = f′(g(x))g′(x)."], ["Marginal sensitivity", "The local derivative of an output with respect to a modeled input."]]),
    lesson("Optimization and related rates", ["Use critical points and endpoints to optimize a continuous model.", "Translate geometric or physical constraints before differentiating."], "Optimization begins with a model and feasible domain. Find critical points where the derivative is zero or undefined, include interval endpoints, and compare objective values. A zero derivative is only a candidate, not automatically a maximum or minimum. Related-rates problems differentiate a constraint with respect to time, preserving dependence between variables. In biomedical design, optimization targets should include constraints such as stress, nutrient delivery, or measurement range.", "A scaffold design minimizes a cost function over 0 ≤ porosity ≤ 1; an unconstrained stationary point outside that interval is infeasible and must be discarded.", numeric("A positive rectangular construct has fixed perimeter 20 cm. What side length (cm) gives the maximum area?", 5, "cm", "Let sides be x and 10−x; maximize A=x(10−x) on 0<x<10.", "A=10x−x², so A′=10−2x=0 at x=5 cm. This is the maximum; the square maximizes area for fixed perimeter."), [["Critical point", "An interior candidate for an extremum where a derivative is zero or undefined."], ["Feasible domain", "The set of inputs that satisfy a model's physical and design constraints."]]),
    lesson("Definite integrals and the fundamental theorem", ["Interpret an integral as signed accumulation.", "Use integration to recover a state from its rate."], "The definite integral ∫ₐᵇ f(x)dx accumulates signed contributions; geometric area is only one interpretation. The fundamental theorem of calculus connects accumulation to antiderivatives and differentiation. If C′(t) is a production-minus-clearance rate, then C(t) = C(0) + ∫₀ᵗ C′(τ)dτ. Units multiply: (mg/L)/min integrated over min yields mg/L. Numerical quadrature is needed when analytic antiderivatives are unavailable or the rate is measured data.", "If a constant infusion adds 2 mg/L per hour for 3 hours with no clearance, concentration rises by 6 mg/L.", numeric("A measured uptake rate is constant at 1.8 mg/min for 5 minutes. How much material is accumulated in mg?", 9, "mg", "Integrate the constant rate over the time interval.", "Accumulated amount = 1.8 mg/min × 5 min = 9 mg."), [["Definite integral", "The signed accumulation of a quantity over an interval."], ["Fundamental theorem of calculus", "The result linking derivatives and integrals: accumulation can be evaluated using an antiderivative."]]),
  ], { prompt: "A concentration sensor reports C(t)=C₀e^(−kt) after washout. Explain how a semilog plot estimates k, identify the units of k, and state one reason measured points may deviate from a straight line.", rubric: ["Takes ln(C/C₀)=−kt and identifies slope −k", "States k has inverse-time units", "Names a plausible model or measurement limitation such as background offset, multiple compartments, sensor lag, or non-first-order clearance"] }),

  course("calculus-2", "MATH 152", "Calculus II: Integration, Series & Applications", "Mathematics", "Year 1", 4, "Calculus I", "Advanced integration, applications of accumulation, sequences and series, and power-series approximations for quantitative science.", ["Select and justify an integration method.", "Set up integrals for work, area, and volume.", "Test convergence of standard series.", "Use Taylor approximations with an error interpretation."], ["calculus"], ["biomedical", "robotics", "tissue", "geroscience"], [
    lesson("Integration techniques and improper integrals", ["Choose substitution, parts, or partial fractions from structure.", "Determine whether an improper integral converges."], "Integration by substitution reverses the chain rule; integration by parts reverses the product rule. Partial fractions decompose rational functions once the denominator is factored. Improper integrals require limits at infinite endpoints or singularities; finite-looking area is not sufficient to guarantee convergence. In pharmacokinetics, an exposure integral AUC = ∫₀∞ C(t)dt converges only if concentration declines fast enough.", "For C(t)=C₀e^(−kt), k>0, the total exposure is ∫₀∞C₀e^(−kt)dt = C₀/k.", numeric("Evaluate ∫₀∞ 4e^(−2t) dt.", 2, "", "The antiderivative is −2e^(−2t); evaluate it at infinity and zero.", "The integral is 4 × (1/2) = 2; exponential decay with positive rate is integrable."), [["Improper integral", "An integral defined using a limit because of an infinite interval or an unbounded integrand."], ["Area under the curve (AUC)", "An accumulated exposure measure given by integrating concentration over time."]]),
    lesson("Sequences, series, and approximation error", ["Select a convergence test for a series.", "Use Taylor polynomials with a remainder interpretation."], "A series is the limit of its partial sums; terms approaching zero is necessary but not sufficient for convergence. Geometric, p-series, comparison, ratio, root, and alternating tests answer different structural questions. Taylor expansion approximates a smooth function near a center, with error controlled by omitted derivatives over a stated interval. Truncating a series should be justified by an error bound when a numerical result supports a design or scientific conclusion.", "For |x|<1, 1/(1−x)=Σxⁿ. At x=0.2, truncating after n=2 gives 1.24 versus 1.25; the tail is 0.2³/(1−0.2)=0.01.", choice("Which statement is sufficient to establish convergence of Σₙ₌₁∞ 1/n²?", ["The terms tend to zero", "It is a p-series with p = 2 > 1", "The terms are positive", "The partial sums initially increase"], 1, "Use a test that gives a conclusion, not only a necessary condition.", "The p-series test proves convergence for p>1. Terms tending to zero is necessary but alone does not establish convergence."), [["p-series", "A series Σ1/nᵖ; it converges exactly when p>1."], ["Taylor remainder", "A bound or expression for the error left after truncating a Taylor expansion."]]),
    lesson("Applications of integration: work and accumulation", ["Set bounds from the physical process before integrating.", "Interpret a variable-force integral and check units."], "A definite integral accumulates a changing quantity over a domain. Work by a one-dimensional position-dependent force is W=∫ₐᵇF(x)dx; area, volume, average value, and exposure use the same accumulation idea with different measures. Bounds encode the physical domain, and units multiply through the integral. For measured data, numerical quadrature is an approximation whose error depends on sampling and curvature.", "If a spring-like actuator applies F(x)=4x N from x=0 to 3 m, W=∫₀³4x dx=18 J.", numeric("A force F(x)=4x N acts from x=0 to 3 m. How much work is done in joules?", 18, "J", "Integrate 4x from 0 to 3; work has units N·m.", "W=[2x²]₀³=18 N·m=18 J."), [["Work integral", "Accumulated mechanical energy transfer W=∫F·dx along a displacement."], ["Average value", "The integral of a function over an interval divided by interval length."]]),
    lesson("Power series and Taylor error", ["Build a Taylor polynomial from derivatives at a center.", "State where a series converges and how truncation error is controlled."], "A Taylor polynomial approximates a smooth function locally from its derivatives at a center. A power series has a radius of convergence; behavior at the endpoints needs a separate test. Taylor theorem bounds the remainder using a higher derivative over the interval, which matters when an approximation feeds a design calculation. Small error at one input does not guarantee accuracy over a larger domain.", "For eˣ near x=0, the quadratic approximation at x=0.2 is 1+0.2+0.2²/2=1.22; the cubic remainder is under about 0.0017 on that interval.", numeric("Using 1+x+x²/2 to approximate eˣ at x=0.2, what value do you obtain?", 1.22, "", "Substitute x=0.2 into the quadratic Taylor polynomial.", "1+0.2+(0.2)²/2=1+0.2+0.02=1.22."), [["Radius of convergence", "Distance from a power-series center within which the series converges; endpoints need separate tests."], ["Taylor remainder", "The error between a function and its finite Taylor polynomial, bounded using higher derivatives."]]),
  ], { prompt: "A modeled tissue concentration is c(r)=c₀(1−r²/R²) in a cylindrical cross-section. Explain how the radial Jacobian changes the total amount integral and compare it with the center-concentration × area approximation.", rubric: ["Uses dA=2πr dr or r dr dθ", "Sets radial bounds 0 to R and integrates the profile", "Notes that center concentration times area overestimates because concentration falls toward the edge"] }),

  course("calculus-3", "MATH 253", "Calculus III: Multivariable & Vector Calculus", "Mathematics", "Year 2", 4, "Calculus II; Linear Algebra recommended", "Vector-valued geometry, partial derivatives, constrained optimization, multiple integrals, and vector calculus for fields, flux, and spatially distributed biological systems.", ["Compute directional derivatives and interpret gradients.", "Optimize multivariable functions with and without constraints.", "Set up multiple integrals in appropriate coordinates.", "Relate line and surface integrals to vector-field theorems."], ["multivariable", "transport"], ["biomedical", "robotics", "tissue", "geroscience"], [
    lesson("Vectors, partial derivatives, and gradients", ["Represent vectors in coordinate frames.", "Compute gradients and directional derivatives."], "A scalar field assigns a value to each point; a vector field assigns a vector. Partial derivatives vary one coordinate while holding the others fixed. The gradient ∇f points in the direction of steepest local increase; its dot product with a unit direction gives the directional derivative. These local models support sensitivity analysis in dose, geometry, and field models, but depend on differentiability and a stated coordinate frame.", "For f(x,y)=x²+3y², ∇f=(2x,6y), so ∂f/∂y at (1,−1) is −6.", numeric("For f(x,y)=x²+3y², what is ∂f/∂y at (1,−1)?", -6, "", "Differentiate with respect to y while holding x constant: 6y.", "∂f/∂y=6y; at y=−1 this equals −6."), [["Gradient", "Vector of first partial derivatives; it points toward steepest local increase for a differentiable scalar field."], ["Directional derivative", "The local rate of change of a scalar field along a specified unit direction."]]),
    lesson("Multivariable optimization and constraints", ["Classify stationary points using second derivatives.", "Use Lagrange multipliers for a smooth geometric constraint."], "An unconstrained interior optimum satisfies ∇f=0, then second derivatives classify local curvature. On a smooth constraint g(x)=c, an optimum may satisfy ∇f=λ∇g. Boundary points and feasible ranges still need checking. In design problems, an objective and constraint encode different engineering statements; a mathematically optimal point outside biological or manufacturing limits is not an acceptable design.", "The maximum of f=x+y on the unit circle occurs at x=y=1/√2, so f=√2.", numeric("What is the maximum of f=x+y subject to x²+y²=1? Enter a decimal.", 1.4142, "", "The gradient of x+y points along (1,1); normalize that vector to the unit circle.", "At x=y=1/√2, f=√2≈1.4142.", 0.01), [["Lagrange multiplier", "A scalar relating objective and constraint gradients at a regular constrained optimum."], ["Hessian", "Matrix of second partial derivatives used to assess local curvature."]]),
    lesson("Multiple integrals and coordinate transforms", ["Choose bounds for an area or volume integral.", "Include the Jacobian in a coordinate change."], "A multiple integral accumulates a density over a region. In polar coordinates, dA=r dr dθ; the factor r is the Jacobian that accounts for the changing area of a coordinate cell. Cylindrical and spherical coordinates have their own volume Jacobians. Sketch the region before writing bounds. For tissue concentration c(x), total amount is ∫Ωc(x)dV; concentration times volume is valid only when c is uniform.", "The area of the unit disk is ∫₀²π∫₀¹ r dr dθ=π.", numeric("Evaluate ∫₀²π∫₀¹ r dr dθ, the area of the unit disk.", 3.1416, "", "Integrate r from 0 to 1, then the resulting constant from 0 to 2π.", "The integral is 2π×(1/2)=π≈3.1416.", 0.01), [["Jacobian determinant", "The local area or volume scaling factor introduced by a coordinate transformation."], ["Volume density", "A quantity per unit volume that is integrated over a region to obtain a total."]]),
    lesson("Line integrals, flux, and integral theorems", ["Interpret line integrals as work or circulation.", "Choose Green's, Stokes', or divergence theorem from the geometry."], "A line integral accumulates a field along an oriented curve; a flux integral measures a field component crossing an oriented boundary. Green's theorem relates planar circulation or flux to an area integral, Stokes' theorem relates boundary circulation to curl through a surface, and the divergence theorem relates outward flux through a closed surface to divergence in the enclosed volume. Orientation and smoothness conditions matter. These theorems can simplify calculations and provide checks on numerical field measurements.", "For F=(x,y,z), div F=3. Its outward flux through the unit sphere is 3 times the sphere's volume, or 4π.", choice("Which theorem relates outward flux across a closed surface to the volume integral of divergence?", ["Fundamental theorem of calculus", "Divergence theorem", "Chain rule", "Mean value theorem"], 1, "This theorem connects a closed boundary to the volume it encloses.", "The divergence theorem states that outward flux through a closed surface equals the volume integral of divergence over its interior."), [["Divergence", "A scalar measure of local source or sink strength of a vector field."], ["Flux integral", "A surface integral of the field component normal to an oriented boundary."]]),
  ], { prompt: "A tissue has oxygen flux J=−D∇C through an irregular boundary. Explain how you would choose a surface orientation, compute total oxygen transfer, and check whether a divergence-theorem formulation is valid.", rubric: ["Defines the outward normal and sign convention", "Sets up ∫S J·n dA over the physical boundary", "Checks smoothness/closed-surface conditions and relates net flux to volume sources or sinks"] }),

  course("linear-algebra", "MATH 221", "Linear Algebra for Modeling & Robotics", "Mathematics", "Year 2", 3, "Calculus I; matrix arithmetic", "Vectors, matrices, eigenstructure, least squares, and linear transformations applied to state estimation, circuit networks, and robot coordinates.", ["Solve linear systems and diagnose singularity.", "Interpret bases, rank, and null spaces.", "Use eigenvalues to describe linear dynamics.", "Fit an overdetermined model by least squares."], ["linearAlgebra", "engineeringMath"], ["biomedical", "robotics", "tissue"], [
    lesson("Linear systems, elimination, and rank", ["Solve Ax=b with elimination.", "Interpret pivots and rank as information about solutions."], "Gaussian elimination transforms a system using reversible row operations. A pivot in every variable column gives a unique solution; a missing pivot can imply free variables or inconsistency depending on the augmented matrix. Rank measures independent constraints. In engineering, singular or ill-conditioned matrices can make a model sensitive to noise even when an exact solution exists. Scaling, condition numbers, and independent validation matter when interpreting computed parameters.", "The system x+y=3, 2x+2y=6 has rank 1 and infinitely many solutions; the second equation adds no independent constraint.", numeric("Solve x+y=7 and x−y=1. What is x?", 4, "", "Add the equations to eliminate y.", "Adding gives 2x=8, so x=4 and y=3."), [["Rank", "The number of linearly independent rows or columns in a matrix."], ["Condition number", "A measure of how strongly solution error may amplify input or measurement error."]]),
    lesson("Vector spaces, bases, and coordinate transforms", ["Test linear independence and span.", "Distinguish a geometric vector from its coordinates in a basis."], "A basis is a linearly independent set that spans a vector space. Coordinates depend on that basis, while the underlying vector does not. Change-of-basis matrices convert coordinates between descriptions. In robotics, rotation matrices represent the same physical vector in different frames and must be orthogonal with determinant +1 for a proper rotation. A basis with poor scaling can make numerical estimates unstable even when mathematically valid.", "A 90° planar rotation maps (1,0) to (0,1); the vector's coordinates change because its orientation changes relative to the frame.", numeric("A planar vector (3,0) is rotated counterclockwise by 90°. What is its new y-coordinate?", 3, "", "Apply R=[[0,−1],[1,0]] to the vector.", "R[3,0]ᵀ = [0,3]ᵀ, so the new y-coordinate is 3."), [["Span", "All linear combinations of a set of vectors."], ["Basis", "A linearly independent set that spans the vector space."]]),
    lesson("Eigenvalues and linear dynamical systems", ["Interpret eigenvalues of a transition matrix.", "Connect diagonalization to mode-by-mode behavior."], "For ẋ=Ax, eigenvectors define invariant directions and eigenvalues determine growth, decay, or oscillation along modes. Negative real parts imply asymptotic decay for a continuous-time linear system; any eigenvalue with positive real part signals instability. If A is not diagonalizable, generalized eigenvectors produce polynomial factors multiplying exponentials. A local linearization near a nonlinear equilibrium is useful only near that equilibrium and under its stability assumptions.", "For ẋ=−2x, the solution decays as e^(−2t), with time constant 0.5 in the chosen time unit.", choice("For a continuous-time linear system ẋ=Ax, what condition guarantees asymptotic stability of the origin?", ["Every eigenvalue has negative real part", "Every eigenvalue is positive", "The trace is zero", "Every matrix entry is negative"], 0, "The modal solutions contain exponential factors e^(λt).", "All eigenvalues with negative real parts produce decaying modes, which is the continuous-time asymptotic-stability condition for a linear system."), [["Eigenvalue", "A scalar λ for which Av=λv for some nonzero vector v."], ["Asymptotic stability", "Small perturbations decay back toward an equilibrium as time increases."]]),
    lesson("Least squares and data fitting", ["Derive normal equations for a full-rank linear model.", "Interpret residuals and avoid overclaiming from fit quality."], "When Ax=b is overdetermined, least squares chooses x minimizing ||Ax−b||². If A has full column rank, the normal equations AᵀAx=Aᵀb yield the solution. Residuals reveal mismatch but should be inspected for structure; a small residual does not validate assumptions or causal meaning. Scaling, collinearity, outliers, and uncertainty can change estimates. Weighted least squares is appropriate when measurement variance differs and weights are justified.", "For observations y=[1,3] at x=[0,2], the least-squares line has slope 1 and intercept 1, fitting both points exactly.", numeric("The points (0,2) and (2,6) lie on a line y=a+bx. What is slope b?", 2, "", "Compute change in y divided by change in x.", "b=(6−2)/(2−0)=2."), [["Least squares", "Parameter estimation that minimizes the sum of squared residuals."], ["Residual", "Observed value minus model-predicted value."]]),
  ], { prompt: "Two sensors estimate the same tissue displacement but their design matrix has nearly collinear columns. Explain why a tiny residual can coexist with unreliable parameter estimates, and propose one diagnostic or redesign.", rubric: ["Identifies ill-conditioning/collinearity", "Connects it to large parameter changes under small noise", "Suggests condition number, uncertainty analysis, or a more informative sensor geometry"] }),

  course("differential-equations", "MATH 240", "Differential Equations for Living & Engineered Systems", "Mathematics", "Year 2", 3, "Calculus I; linear algebra recommended", "Build, solve, and interpret first- and second-order differential equations, coupled systems, stability, and numerical integration for biological and robotic dynamics.", ["Classify ODEs and choose solution methods.", "Interpret equilibria, time constants, and stability.", "Model coupled state variables as a vector system.", "Check numerical solutions against physical constraints."], ["diffeqs", "engineeringMath", "numerical"], ["biomedical", "robotics", "geroscience", "tissue"], [
    lesson("First-order models and time constants", ["Solve separable and linear first-order ODEs.", "Interpret equilibrium and characteristic time."], "A first-order linear model ẋ = −k(x−x*) has equilibrium x* and solution x(t)=x*+(x₀−x*)e^(−kt). Its time constant τ=1/k is the time to complete about 63% of a step response. Exponential models appear in washout, relaxation, charging, and simple population dynamics. Units constrain k to inverse time. Initial conditions are part of a complete prediction; the differential equation alone gives a family of trajectories.", "A sensor response with τ=4 s reaches about 63% of its final step change after 4 s and about 95% after 3τ, under the first-order model.", numeric("For ẋ = −0.25x with x(0)=8, what is x(4)? Give a value to two decimals.", 2.94, "", "Use x(t)=x₀e^(−kt).", "x(4)=8e^(−0.25×4)=8e^(−1)≈2.94."), [["Equilibrium", "A state where the derivative is zero under the model."], ["Time constant", "For a first-order exponential process, τ=1/k; it sets the characteristic response timescale."]]),
    lesson("Second-order systems and mechanical response", ["Relate damping ratio to qualitative transient behavior.", "Write a mechanical model from force balance."], "A mass-spring-damper system follows m ẍ + c ẋ + kx = F(t). Natural frequency ωn=√(k/m) and damping ratio ζ=c/(2√(km)) characterize the unforced response. ζ<1 gives oscillatory decay, ζ=1 critical damping, and ζ>1 overdamping. Units and free-body diagrams prevent sign errors. Real tissue and robotics mechanisms may be nonlinear or viscoelastic, so a linear spring-damper is a local or frequency-limited approximation.", "For m=1 kg and k=100 N/m, ωn=10 rad/s. Critical damping is ccrit=2√(km)=20 N·s/m.", numeric("For m=2 kg and k=50 N/m, compute the undamped natural frequency ωn in rad/s.", 5, "rad/s", "Use ωn=√(k/m).", "ωn=√(50/2)=√25=5 rad/s."), [["Damping ratio ζ", "A dimensionless ratio indicating underdamped, critically damped, or overdamped behavior."], ["Natural frequency", "The characteristic angular frequency of an unforced system before damping effects are considered."]]),
    lesson("Coupled systems, equilibria, and stability", ["Linearize a nonlinear system near an equilibrium.", "Use eigenvalues to classify local stability."], "A coupled model ẋ=f(x) can be linearized near equilibrium x* using the Jacobian J=∂f/∂x|x*. Eigenvalues of J describe local modes: negative real parts indicate local decay, positive real parts indicate instability, and purely imaginary or zero modes require further analysis. Nullclines help visualize equilibria in two dimensions. Local stability does not guarantee global behavior; other equilibria, boundaries, and nonlinear limit cycles may matter.", "In a two-state linear model with J=diag(−1,−3), perturbations decay independently with time constants 1 and 1/3 time units.", choice("A two-state continuous system has Jacobian eigenvalues −2 and +0.1 at an equilibrium. What can be concluded locally?", ["The equilibrium is asymptotically stable", "The equilibrium is unstable", "The system is periodic", "The equilibrium is globally stable"], 1, "One growing linearized mode is enough to make the equilibrium unstable.", "The positive eigenvalue creates a locally growing perturbation, so the equilibrium is unstable. This does not by itself specify the global trajectory."), [["Jacobian", "Matrix of first partial derivatives of a vector field, used for local linearization."], ["Nullcline", "A set where one state derivative is zero; intersections can identify equilibria."]]),
    lesson("Numerical ODEs and error control", ["Apply forward Euler and recognize its limitations.", "Choose a step size based on stability and accuracy, not convenience alone."], "Forward Euler updates xₙ₊₁=xₙ+h f(tₙ,xₙ); it is first-order accurate globally and can be unstable for a step size that is too large. Higher-order Runge-Kutta methods improve accuracy per step but still require convergence checks. Compare solutions at h and h/2, monitor units and conserved quantities, and document solver tolerances. For stiff biochemical systems, explicit methods may need impractically small steps; implicit solvers can be more stable.", "For ẋ=−x, x₀=1, Euler with h=0.1 gives x₁=0.9; exact x(0.1)=e^(−0.1)≈0.905, showing a small first-step error.", numeric("For ẋ=2, x₀=3, apply one forward-Euler step with h=0.25. What is x₁?", 3.5, "", "Compute x₁=x₀+h f(x₀).", "x₁=3+0.25×2=3.5."), [["Forward Euler", "An explicit first-order method that advances a state using its current derivative."], ["Stiff system", "A system with widely separated timescales that can make explicit integration inefficient or unstable."]]),
  ], { prompt: "A fitted cell-population model reproduces the first 24 hours but predicts negative cell counts later. Give two model or numerical causes and a validation change that would reveal the failure earlier.", rubric: ["Names model-structure mismatch or extrapolation beyond fit domain", "Names numerical step-size/stability or missing nonnegativity constraints", "Suggests longer-horizon or step-refinement/independent-data validation"] }),

  course("statistics", "STAT 210", "Probability, Biostatistics & Experimental Design", "Quantitative methods", "Year 2", 3, "Algebra; calculus recommended", "Probability, estimation, hypothesis testing, regression, and design principles for biological and engineering experiments, with reproducibility and uncertainty at the center.", ["Distinguish sampling variability from measurement error.", "Choose an analysis matched to design and outcome.", "Interpret confidence intervals, p-values, and effect sizes.", "Design controls, replication, randomization, and blinding."], ["statistics", "biology"], ["biomedical", "geroscience", "tissue"], [
    lesson("Probability, distributions, and sampling", ["Use conditional probability and Bayes' rule.", "Explain why a sample mean varies across repeated samples."], "A probability model describes variability under stated assumptions. The expected value is a long-run average, not necessarily a typical observed value. Sampling distributions quantify uncertainty in estimates; for independent observations with finite variance, the standard error of the mean is approximately s/√n. Independence is a design assumption, not a consequence of taking many measurements. Repeated technical reads of one sample do not replace independent biological replicates.", "If biological replicates have SD=12 units and n=9 independent samples, the standard error of the mean is 12/√9=4 units.", numeric("An experiment has sample SD 10 and n=25 independent biological replicates. What is the standard error?", 2, "", "Compute s/√n.", "SE=10/√25=2 units."), [["Standard deviation", "The spread of observations around their mean in a sample or population model."], ["Standard error", "The uncertainty scale of an estimator across repeated samples; for a mean, approximately s/√n under independence."]]),
    lesson("Estimation, confidence intervals, and effect sizes", ["Interpret an interval as a procedure for repeated sampling.", "Separate magnitude from statistical precision."], "A 95% confidence procedure has 95% long-run coverage when its assumptions hold; after observing a particular interval, it is not correct to say there is a 95% probability the fixed parameter lies inside it in the frequentist model. A narrow interval can reflect precision but not freedom from bias. Report effect sizes and intervals alongside tests, and define the estimand before selecting analysis. Units and the reference comparison make results interpretable.", "If an estimated treatment effect is 4.0 units with 95% CI [1.0, 7.0], the interval excludes zero under that model, but the effect's biological importance still requires context.", choice("A 95% confidence interval for a mean difference is [1, 5]. Which interpretation is best?", ["The fixed mean difference has 95% probability of lying in this realized interval", "The method would cover the true difference in about 95% of repeated samples under its assumptions", "There is a 95% chance the effect is biologically important", "The null hypothesis is exactly 5% likely"], 1, "A frequentist interval describes the long-run behavior of the procedure.", "The 95% refers to repeated-sampling coverage under assumptions. It does not assign a probability to the fixed parameter after the interval is observed."), [["Estimand", "The precisely defined quantity a study aims to estimate, such as a treatment effect in a target population."], ["Effect size", "A quantitative measure of the magnitude of a difference or association."]]),
    lesson("Hypothesis tests and multiple comparisons", ["Interpret p-values conditional on the null and analysis plan.", "Account for multiplicity and distinguish confirmatory from exploratory work."], "A p-value is the probability, under the null model and assumptions, of data at least as incompatible with that model as observed. It is not the probability the null is true, nor a measure of effect size. Multiple testing increases false-positive opportunities; family-wise error or false-discovery-rate procedures address different goals. Pre-specifying primary outcomes, contrasts, and exclusion rules reduces researcher degrees of freedom. A statistically detectable effect can be too small to matter practically.", "If 20 independent null tests each use α=0.05 without correction, the probability of at least one false positive is 1−0.95²⁰≈0.64.", numeric("For 10 independent null tests each at α=0.05, what is the probability of at least one false positive? Enter percent, rounded to a whole number.", 40, "%", "Use 1−(1−α)ⁿ and multiply by 100.", "1−0.95¹⁰≈0.401, or about 40%. Independence is assumed for this calculation.", 1.2), [["p-value", "Probability under a specified null model of data at least as extreme as observed, subject to the test assumptions."], ["False discovery rate", "The expected fraction of false positives among rejected hypotheses under a specified multiple-testing procedure."]]),
    lesson("Experimental design, regression, and reproducibility", ["Use randomization and blocking to reduce confounding.", "Assess model residuals and distinguish replication levels."], "Randomization supports unbiased comparisons; blocking controls known nuisance variability; blinding reduces measurement and analysis bias. Replication should match the unit of inference: cells nested within wells or wells nested within animals are not automatically independent. Regression describes conditional relationships under a model and can adjust measured covariates, but unmeasured confounding remains possible. Residual plots, influence checks, preregistered outcomes, and transparent code help assess reliability.", "In a 2-condition study across 6 independent donors, donor is a biological replication/blocking factor; measuring 100 cells per donor improves within-donor precision but does not create 600 independent donors.", choice("A study measures 100 cells from each of 4 animals per group. What is the primary biological sample size per group?", ["400", "100", "4", "40,000"], 2, "Cells are nested within animals; identify the independent unit assigned to treatment.", "If treatment was assigned by animal, the primary biological sample size is 4 animals per group. Cell-level observations are nested and require a hierarchical analysis."), [["Pseudoreplication", "Treating non-independent subsamples as independent experimental replicates."], ["Blocking", "Grouping experimental units by a nuisance factor so treatment comparisons are made within more homogeneous groups."]]),
  ], { prompt: "A pilot reports p=0.04 for one of 18 measured biomarkers, with no pre-specified primary endpoint and three technical replicates per sample. Write a cautious interpretation and a confirmatory redesign.", rubric: ["Does not interpret p as probability the null is true", "Notes multiplicity and that technical replicates do not increase biological n", "Proposes pre-specified primary outcome, powered biological replication, randomization/blinding, and multiplicity plan"] }),

  course("physics-mechanics", "PHYS 201", "Physics: Mechanics for Biomedical Engineers", "Physics", "Year 1", 4, "Algebra and trigonometry; calculus taken concurrently", "Kinematics, forces, energy, momentum, rotation, and material response taught through free-body diagrams and experimental checks.", ["Build a free-body diagram with consistent axes.", "Apply conservation laws and Newton's laws.", "Quantify torque, angular momentum, and rotational energy.", "Check mechanical predictions against units and limiting cases."], ["mechanics", "engineeringMath"], ["biomedical", "robotics", "tissue"], [
    lesson("Kinematics and force balance", ["Translate position data into velocity and acceleration.", "Apply Newton's second law along chosen axes."], "Kinematics describes motion; dynamics connects motion to interactions. Newton's second law ΣF=ma applies to the net external force on a defined system. A free-body diagram includes only forces acting on that system, not the forces it exerts. Coordinate choices should simplify constraints and signs should be stated. In tissue or device mechanics, effective mass and force may depend on scale and constitutive behavior, so identify the system boundary first.", "A 0.20 kg instrument package accelerating upward at 2 m/s² has tension T−mg=ma, so T=0.20(9.81+2)=2.36 N.", numeric("A 3 kg cart experiences a net horizontal force of 12 N. What is its acceleration in m/s²?", 4, "m/s²", "Use ΣF=ma.", "a=12/3=4 m/s²."), [["Free-body diagram", "A diagram of external forces and moments acting on a chosen system."], ["Net force", "The vector sum of external forces that determines translational acceleration."]]),
    lesson("Work, energy, and power", ["Use work-energy when forces vary with position.", "Distinguish conservative energy storage from dissipation."], "Work is W=∫F·dx and changes kinetic energy according to the work-energy theorem. Conservative forces have path-independent work and can be represented by potential energy. Friction and viscous drag dissipate mechanical energy into other forms. Power P=dW/dt=F·v is the rate of energy transfer. In biological systems, mechanical work couples to chemical energy, but efficiency depends on the defined input and output boundaries.", "Compressing a linear spring by x stores U=½kx². A spring with k=200 N/m compressed 0.05 m stores 0.25 J.", numeric("A 2 kg object moving at 3 m/s has what kinetic energy in joules?", 9, "J", "Use K=½mv².", "K=½×2×3²=9 J."), [["Work", "Energy transfer through force acting along a displacement."], ["Power", "Rate of energy transfer, such as mechanical force times velocity in one-dimensional motion."]]),
    lesson("Momentum, collisions, and impulse", ["Apply momentum conservation to a defined isolated system.", "Relate impulse to force-time history."], "Linear momentum is p=mv; impulse J=∫Fdt equals change in momentum. Total momentum is conserved when net external impulse is negligible, even when kinetic energy is not. An elastic collision conserves kinetic energy as well; an inelastic collision converts some organized kinetic energy into deformation, heat, or sound. In impact biomechanics, force peaks depend on compliance and pulse duration, so the impulse alone does not specify tissue injury risk.", "A 0.15 kg ball changes velocity from +8 to −4 m/s. Its impulse is 0.15(−12)=−1.8 N·s.", numeric("A 0.10 kg cart moving at 5 m/s sticks to a stationary 0.40 kg cart. What is their shared speed in m/s?", 1, "m/s", "Conserve momentum: m₁v₁+m₂v₂=(m₁+m₂)v_f.", "v_f=(0.10×5)/(0.10+0.40)=1 m/s."), [["Impulse", "The time integral of force, equal to momentum change."], ["Inelastic collision", "A collision in which total momentum is conserved for an isolated system but kinetic energy is not."]]),
    lesson("Rotation, torque, and material response", ["Calculate torque about a stated axis.", "Relate stress and strain to a material model."], "Torque is τ=r×F and depends on the reference axis and lever arm. Rotational dynamics uses Στ=Iα for a rigid body about a fixed axis. For small elastic deformation, engineering stress σ=F/A and strain ε=ΔL/L; Young's modulus E=σ/ε in a linear uniaxial regime. Biological tissues are often anisotropic, nonlinear, and viscoelastic, so a single elastic modulus is only a defined test-condition summary.", "A 10 N force perpendicular to a 0.25 m lever arm produces 2.5 N·m torque.", numeric("A 30 N force acts perpendicular to a hinge at a 0.20 m moment arm. What is the torque magnitude in N·m?", 6, "N·m", "Torque magnitude is rF sin θ; here θ=90°.", "τ=0.20×30=6 N·m."), [["Torque", "The rotational effect of a force about a specified point or axis."], ["Young's modulus", "The slope of a linear stress-strain relation in a specified regime and test direction."]]),
  ], { prompt: "A tendon specimen's apparent modulus doubles when pull direction changes. Explain why this need not be a measurement error and propose the metadata needed to compare the values across labs.", rubric: ["Identifies anisotropy or orientation-dependent fiber recruitment", "Mentions nonlinear/viscoelastic behavior or preload/strain-rate effects", "Specifies orientation, geometry, hydration, temperature, strain rate, and modulus definition"] }),

  course("physics-em", "PHYS 202", "Physics: Electricity & Magnetism", "Physics", "Year 1", 4, "Calculus I; Physics: Mechanics recommended", "Electric fields, circuits, magnetic forces, and induction as foundations for instrumentation, stimulation, sensing, and electrochemical biology.", ["Use field and potential models for charge distributions.", "Analyze resistive-capacitive networks.", "Apply magnetic-force and induction laws.", "Relate circuit measurements to sensor loading and safety limits."], ["physicsEM", "circuits"], ["biomedical", "robotics"], [
    lesson("Electric fields, potential, and capacitance", ["Connect electric field to force and potential difference.", "Use capacitor geometry and energy relations."], "Electric field E is force per unit positive test charge; potential difference is energy per charge. For a parallel-plate capacitor, C≈εA/d when edge effects are small. Stored energy is U=½CV². Conductors redistribute charge until electrostatic equilibrium is reached. In physiological systems, membranes act as thin capacitors separating ionic solutions; fields and potentials depend on both charge distribution and boundary conditions.", "A 2 μF capacitor at 5 V stores U=½CV²=25 μJ.", numeric("A 10 μF capacitor is charged to 3 V. How much energy is stored in μJ?", 45, "μJ", "Use U=½CV² and convert farads to microfarads consistently.", "U=½×10 μF×9 V²=45 μJ."), [["Electric potential", "Electric potential energy per unit charge at a point."], ["Capacitance", "Charge stored per voltage difference, C=Q/V in a linear capacitor."]]),
    lesson("Current, resistance, and RC transients", ["Apply Kirchhoff's laws to lumped circuits.", "Predict exponential charging or discharging behavior."], "Current is charge flow per time. Kirchhoff's current law expresses charge conservation at a node; voltage law follows energy conservation around a loop. Ohm's law V=IR applies to an ohmic element within its operating regime. For a series RC circuit, τ=RC and a step response approaches its final value exponentially. Instrument input impedance can load a high-impedance sensor and alter the quantity being measured.", "For R=100 kΩ and C=10 μF, τ=RC=1 s; after one time constant a charging capacitor reaches about 63% of its final value.", numeric("A 2 kΩ resistor is in series with a 5 μF capacitor. What is the RC time constant in milliseconds?", 10, "ms", "Convert kΩ and μF so the product is in seconds.", "τ=2000 Ω×5×10⁻⁶ F=0.010 s=10 ms."), [["Kirchhoff's current law", "At a circuit node, total current entering equals total current leaving."], ["Time constant τ", "For a first-order RC circuit, the product RC that sets the exponential response timescale."]]),
    lesson("Magnetic forces and induction", ["Use the right-hand rule for magnetic forces.", "Apply Faraday's law to changing magnetic flux."], "A moving charge experiences magnetic force qv×B; current-carrying conductors experience a related force. Magnetic forces act perpendicular to velocity and field, changing direction more readily than speed for an isolated charge. Faraday's law states that changing magnetic flux induces an electromotive force. Lenz's law sets the direction to oppose the change in flux. Sensors, motors, MRI coils, and inductive coupling rely on these principles, with geometry and time-varying fields essential.", "A coil's flux changes from 0 to 0.02 Wb in 0.01 s. One turn has induced emf magnitude |ΔΦ/Δt|=2 V.", numeric("A 50-turn coil experiences a flux change of 0.004 Wb per turn in 0.02 s. What is the induced emf magnitude in volts?", 10, "V", "Use |ε|=N|ΔΦ/Δt|.", "|ε|=50×0.004/0.02=10 V."), [["Magnetic flux", "The surface integral of magnetic field through an oriented area."], ["Lenz's law", "The induced current direction opposes the change in magnetic flux that produced it."]]),
    lesson("Electrodes, impedance, and measurement", ["Interpret impedance as frequency-dependent opposition to current.", "Distinguish electrode polarization from tissue signal."], "Biopotential measurements sit on a coupled electrode-electrolyte-tissue interface. A simple model includes solution resistance, double-layer capacitance, charge-transfer resistance, and half-cell potential, but real interfaces are distributed and frequency-dependent. High input impedance limits loading; differential amplification rejects common-mode signals only when electrode impedances and leads are well matched. Safety analysis considers current density, charge balance, contact area, and waveform, not voltage alone.", "A 1 MΩ sensor source connected to a 1 MΩ input forms a divider and loses half its voltage; a 100 MΩ input reduces this loading substantially.", numeric("A 1 MΩ source drives a 9 MΩ input through a simple divider. What fraction of source voltage appears at the input?", 0.9, "fraction", "Use Vout/Vin=Rin/(Rsource+Rin).", "9/(1+9)=0.90, so 90% of the source voltage appears at the input."), [["Input impedance", "The effective impedance seen by a source at an instrument input; finite values can load the source."], ["Common-mode rejection", "An amplifier's ability to suppress voltage shared by both inputs while amplifying their difference."]]),
  ], { prompt: "A high-impedance microelectrode records a smaller signal after connecting a digitizer. Explain loading with a divider model and give two circuit or measurement changes that test whether the loss is electrical rather than biological.", rubric: ["Models electrode/source impedance in series with finite input impedance", "Predicts attenuation from the divider", "Suggests higher input impedance, buffer amplifier, impedance sweep, or dummy-signal control"] }),

  course("programming", "ENGR 210", "Programming & Numerical Methods for Bioengineering", "Computing", "Year 2", 3, "Algebra; one programming language helpful", "Reproducible scientific computing, data structures, visualization, numerical integration, model fitting, and error analysis for experimental and engineered systems.", ["Write modular code with explicit inputs and outputs.", "Select numerical methods and diagnose error.", "Fit models without confusing interpolation and validation.", "Make reproducible plots and document data provenance."], ["numerical", "engineeringMath"], ["biomedical", "robotics", "geroscience", "tissue"], [
    lesson("Data structures, units, and reproducible code", ["Represent observations with explicit units and metadata.", "Write small functions that can be checked independently."], "Scientific programs should make assumptions visible: units, missing-data handling, input ranges, and transformations belong in data contracts. Vectors and tables store repeated measurements; dictionaries or records preserve sample metadata. Pure functions are easier to test because identical inputs produce identical outputs without hidden state. Versioned code, immutable raw data, and environment records make a result auditable and reproducible.", "Store each sample's treatment, donor, batch, and measurement unit together; keep the raw file unchanged and write cleaned outputs as a derived artifact.", choice("Which code practice most improves reproducibility of a data analysis?", ["Overwrite raw measurements after filtering", "Record the exact input data, parameters, and code version", "Use hidden global variables to avoid repeated inputs", "Round values before all calculations"], 1, "A later analyst needs enough provenance to recreate the result.", "Recording raw inputs, parameters, and code version provides an auditable path from data to result. Destructive edits and hidden state make reproduction harder."), [["Pure function", "A function whose output depends only on its explicit inputs and that has no hidden side effects."], ["Data provenance", "The documented origin, transformations, and history of a data object."]]),
    lesson("Numerical integration and differential models", ["Implement a time step and compare solver resolution.", "Track stability and conservation constraints."], "Numerical integration approximates a continuous process from discrete samples. Forward Euler is transparent but first-order accurate and conditionally stable; higher-order Runge-Kutta improves local approximation at added computation. Step size, solver tolerances, stiffness, and measurement noise all affect the answer. Validate by halving the step, checking limiting cases, and comparing against analytic or conservation-based results when available. A visually smooth curve is not evidence of numerical accuracy.", "Integrating ẋ=−x from 0 to 1 with Euler step h=0.1 gives a different result than h=0.01; convergence toward e⁻¹ is the check.", numeric("For ẋ=3, x₀=2, and one Euler step of h=0.4, what is x₁?", 3.2, "", "Use x₁=x₀+h·3.", "x₁=2+0.4×3=3.2."), [["Step size", "The time or spatial increment used by a numerical discretization."], ["Convergence check", "A comparison across refined numerical settings to assess whether the computed solution approaches a stable value."]]),
    lesson("Regression, uncertainty, and validation", ["Separate model fitting from model validation.", "Inspect residuals and quantify parameter uncertainty."], "A regression model estimates parameters by matching predictions to observations under a loss function. Training fit does not measure generalization; independent validation or cross-validation estimates performance on new data. Residual structure signals misspecification, autocorrelation, heteroskedasticity, or unmodeled groups. Parameter uncertainty and predictive uncertainty differ. Avoid leakage: preprocessing, feature selection, and threshold tuning must occur inside each training fold.", "A model with lower training error but higher held-out error may be overfit; simplify it, regularize it, or collect independent data.", choice("Why must scaling be learned separately inside each cross-validation training fold?", ["To prevent information from held-out observations leaking into the fitted pipeline", "To increase the test-set sample size", "To force all residuals to zero", "To guarantee causal inference"], 0, "Any preprocessing informed by held-out data weakens the independence of validation.", "Learning scaling parameters using held-out data leaks information into training. Fit preprocessing within each fold, then apply it unchanged to that fold's held-out observations."), [["Data leakage", "Information from validation or test data unintentionally influencing model fitting or feature selection."], ["Cross-validation", "Repeated partitioning of data into fit and held-out subsets to estimate predictive performance."]]),
    lesson("Visualization and uncertainty communication", ["Choose a plot that matches variable type and comparison.", "Show distributions and uncertainty without obscuring individual observations."], "A plot is a quantitative claim with scales and encoding choices. Show raw observations where possible, distinguish independent samples from subsamples, label units, and explain uncertainty intervals. Bar charts of means hide distribution shape; a zero baseline matters for comparisons of magnitude. Color should not be the only encoding. For time series, indicate sampling, smoothing, and missing intervals. Visual clarity cannot repair a biased design, but it can expose suspicious structure.", "Plotting donor-level points with a paired line can make within-donor treatment effects clearer than two unpaired bars when donors are the randomized blocks.", choice("A paired study measures each donor before and after treatment. Which display best preserves the pairing?", ["Plot each donor's two values connected by a line", "Show only one bar per condition", "Pool every cell and ignore donor identity", "Use a pie chart of the two means"], 0, "The visual should retain which observations belong to the same donor.", "Connecting each donor's measurements preserves within-donor pairing and reveals direction and variability of individual responses."), [["Heteroskedasticity", "Nonconstant variance of model residuals across fitted values or predictors."], ["Paired design", "A design where each unit contributes multiple linked measurements, enabling within-unit comparisons."]]),
  ], { prompt: "A classifier has 99% accuracy on a dataset with 1% positive cases. Explain why this is not sufficient evidence of usefulness and specify at least three additional metrics or validation checks.", rubric: ["Notes a majority-class classifier reaches 99% accuracy", "Adds sensitivity/recall, precision, PR-AUC, calibration, or decision threshold", "Requests held-out/temporal/external validation and leakage review"] }),

  course("statics-materials", "ENGR 220", "Statics & Mechanics of Materials", "Mechanical engineering", "Year 2", 3, "Physics: Mechanics; Calculus I", "Equilibrium, internal loads, stress, strain, and failure criteria as tools for safe devices, fixtures, implants, and bioreactor hardware.", ["Solve force and moment equilibrium.", "Compute axial, torsional, and bending stress.", "Relate material response to boundary conditions.", "Use safety factors with an explicit failure criterion."], ["solidMechanics", "mechanics"], ["biomedical", "robotics", "tissue"], [
    lesson("Free-body diagrams and equilibrium", ["Isolate a body and include all external reactions.", "Solve force and moment balance in 2D."], "A static body satisfies ΣF=0 and ΣM=0. Choose a system boundary, draw applied loads and support reactions, and use moments to remove unknown forces when possible. Distributed loads can be replaced by resultants acting at their centroids. A support model is an assumption: a pin resists translation but not moment; a fixed support resists both. Check that the number of independent equilibrium equations is adequate for the unknown reactions.", "A simply supported beam with a centered point load P has reactions P/2 at each support by symmetry and moment equilibrium.", numeric("A simply supported beam spans 4 m and carries a 600 N point load at midspan. What vertical reaction acts at either support?", 300, "N", "Use symmetry and vertical-force equilibrium.", "The reactions are equal; 2R=600 N, so R=300 N at each support."), [["Resultant load", "A single force equivalent to a distributed load for force and moment balance."], ["Static determinacy", "Whether equilibrium equations are sufficient to solve all support reactions without deformation compatibility."]]),
    lesson("Axial load, stress, and strain", ["Compute normal stress and elastic extension.", "Check units and identify when a linear model applies."], "For an axial member under force F, average normal stress is σ=F/A. In linear elasticity, strain ε=σ/E and extension ΔL=FL/(AE). These relations assume a suitable material model, small deformation, uniform section, and boundary conditions that justify average stress. Stress concentrations around holes or interfaces require local analysis. In soft tissue and hydrogels, E can depend on strain, rate, hydration, and loading direction.", "A 100 mm-long bar with A=10 mm², E=2 GPa, and F=20 N extends ΔL=0.1 mm under the simple axial model.", numeric("A 50 mm² rod carries 500 N axial tension. What is the average stress in MPa?", 10, "MPa", "Compute F/A and note 1 N/mm² = 1 MPa.", "σ=500 N/50 mm²=10 N/mm²=10 MPa."), [["Normal stress", "Axial force divided by cross-sectional area, with sign convention for tension or compression."], ["Engineering strain", "Change in length divided by original length for a uniaxial specimen."]]),
    lesson("Torsion and bending", ["Relate torque to shear stress in a circular shaft.", "Use bending moment to predict normal stress in a beam."], "For a circular shaft in elastic torsion, τ=Tr/J, where T is applied torque, r the radial coordinate, and J the polar second moment. For beam bending, σ=My/I, with maximum magnitude at the outer fiber. Deflection and stress are different design constraints: a component may remain below yield yet be too flexible. Composite, porous, or anisotropic biomaterials require appropriate section properties and material axes.", "A circular shaft's maximum torsional shear occurs at its outer radius; doubling radius also changes J strongly, so geometry cannot be ignored.", choice("In elementary beam bending, where is the magnitude of normal stress greatest?", ["At the neutral axis", "At the outermost fiber farthest from the neutral axis", "Uniformly across the section", "Only at a pin support"], 1, "Use σ=My/I and ask where |y| is largest.", "Bending stress magnitude is proportional to distance from the neutral axis, so it is greatest at the extreme fibers."), [["Neutral axis", "The line in a bent beam where longitudinal normal strain and stress are zero in the elementary model."], ["Polar second moment J", "A geometric section property governing torsional response of a shaft."]]),
    lesson("Failure criteria, fatigue, and design margins", ["Distinguish yield, ultimate, fatigue, and functional failure.", "Calculate and interpret a factor of safety."], "A design criterion specifies what failure means: yielding, fracture, fatigue crack growth, excessive deflection, leakage, or loss of biological function. A factor of safety compares allowable capacity with the modeled demand and does not replace uncertainty analysis. Repeated loading can cause fatigue below monotonic yield stress. Surface finish, sterilization, corrosion, defects, and interface conditions alter reliability. For implants, mechanical acceptance must be connected to biological and clinical performance, not treated as a single material number.", "If a component's allowable load is 900 N and design load is 300 N under the stated model, the load factor is 3; the reliability meaning still depends on uncertainty and failure mode.", numeric("A part has a specified allowable stress of 120 MPa and a calculated maximum stress of 40 MPa. What is the factor of safety?", 3, "", "Divide allowable stress by calculated stress.", "FoS=120/40=3 for this stated failure criterion."), [["Factor of safety", "Allowable capacity divided by modeled demand under a specified failure mode."], ["Fatigue", "Progressive damage under repeated or fluctuating loading, potentially below monotonic strength."]]),
  ], { prompt: "A porous scaffold meets a yield-strength target but collapses under cyclic perfusion. Identify two failure mechanisms missed by a one-time compression test and propose an accelerated but interpretable test plan.", rubric: ["Identifies fatigue, creep, degradation, buckling, or strut damage", "Includes relevant wet/37°C or degradation environment", "Specifies cyclic loading, controls, measured stiffness/porosity/flow, and stopping criteria"] }),

  course("circuits", "EE 230", "Electrical Circuits & Instrumentation", "Electrical engineering", "Year 2", 4, "Physics: Electricity & Magnetism; Calculus I recommended", "Circuit analysis, analog electronics, filters, sensors, noise, and data acquisition for physiological and laboratory measurement.", ["Solve DC networks with Kirchhoff and Thevenin methods.", "Analyze first-order frequency response.", "Select an amplifier topology for a sensor signal.", "Quantify noise, loading, and calibration limits."], ["circuits", "signals"], ["biomedical", "robotics"], [
    lesson("DC network analysis and equivalent circuits", ["Use nodal analysis for multi-branch networks.", "Reduce a source network to Thevenin form."], "Kirchhoff laws yield a linear system for node voltages and branch currents. A Thevenin equivalent replaces a linear two-terminal network with a voltage source and series resistance seen by the load. Equivalent models preserve terminal behavior, not every internal variable. Dependent sources require care when finding resistance. In sensor systems, source resistance and input resistance determine loading and measurement bias.", "A 5 V source with 1 kΩ series resistance driving a 9 kΩ load gives 4.5 V across the load by voltage division.", numeric("A 12 V ideal source feeds a 2 kΩ and 4 kΩ series pair. What is the current in mA?", 2, "mA", "Add series resistances, then use I=V/R.", "I=12 V/6 kΩ=2 mA."), [["Thevenin equivalent", "A two-terminal model consisting of a voltage source in series with an equivalent resistance."], ["Nodal analysis", "A method that solves unknown node voltages using current conservation at each node."]]),
    lesson("Operational amplifiers and analog front ends", ["Apply ideal op-amp assumptions within feedback limits.", "Choose an instrumentation architecture for small differential signals."], "An ideal op amp has very high input impedance and gain, but real devices have finite bandwidth, offset, bias current, noise, and output limits. Negative feedback sets closed-loop gain when the amplifier operates linearly. Instrumentation amplifiers provide high input impedance and common-mode rejection, but electrode mismatch, lead motion, and reference choices still matter. A correct design checks common-mode range, input-referred noise, saturation recovery, and patient isolation requirements before trusting the signal.", "A non-inverting stage with Rf=90 kΩ and Rg=10 kΩ has ideal gain 1+Rf/Rg=10, while actual bandwidth falls as closed-loop gain rises.", numeric("A non-inverting amplifier has Rf=40 kΩ and Rg=10 kΩ. What is its ideal closed-loop gain?", 5, "", "Use Av=1+Rf/Rg.", "Av=1+40/10=5."), [["Common-mode rejection ratio", "The ratio of differential gain to common-mode gain, often reported in decibels."], ["Input-referred noise", "Output noise referred back to the input by dividing by the relevant gain."]]),
    lesson("Filters, sampling, and anti-aliasing", ["Compute a first-order RC cutoff frequency.", "Explain the Nyquist condition and why it is not enough for real signals."], "A first-order low-pass RC filter has fc=1/(2πRC), attenuating frequencies above cutoff. Sampling at fs maps continuous-time frequencies into discrete-time spectra; components above fs/2 alias unless filtered or otherwise constrained. A practical anti-alias filter needs a transition band and attenuation matched to dynamic range and downstream analysis. Digitization also requires adequate resolution, stable timing, and calibrated gain.", "With R=10 kΩ and C=1 μF, fc≈15.9 Hz; a 100 Hz component is strongly attenuated by a single-pole low-pass stage.", numeric("An RC low-pass uses R=1 kΩ and C=10 μF. Estimate the cutoff frequency in Hz.", 15.9, "Hz", "Use fc=1/(2πRC) with SI units.", "RC=0.01 s; fc=1/(2π×0.01)≈15.9 Hz.", 0.3), [["Cutoff frequency", "The characteristic frequency of a filter, defined by a specified response criterion such as −3 dB."], ["Aliasing", "Frequency ambiguity caused by sampling that makes out-of-band components appear at lower frequencies."]]),
    lesson("Sensors, calibration, and uncertainty", ["Model a sensor transfer function and calibration curve.", "Propagate uncertainty to a reported measurement."], "A sensor maps a physical quantity into an electrical signal through a transfer function. Calibration estimates that mapping against known references; validation asks whether it works in the intended context. Hysteresis, drift, cross-sensitivity, temperature, and mounting can dominate nominal resolution. Uncertainty propagation uses derivatives for small independent errors and covariance terms when measurements are correlated. Report range, bandwidth, noise floor, calibration date, and operating conditions with a measurement.", "If V=2x and voltage uncertainty is ±0.02 V, the corresponding first-order x uncertainty is ±0.01 units, assuming slope 2 V/unit and no other error sources.", numeric("A calibrated sensor has V=0.50x+0.10 V. If measured V=2.10 V, what is x?", 4, "units", "Rearrange the calibration: x=(V−0.10)/0.50.", "x=(2.10−0.10)/0.50=4 units."), [["Calibration", "Estimation of a measurement system's relationship to known reference values."], ["Cross-sensitivity", "A sensor response to a variable other than the intended measurand."]]),
  ], { prompt: "A biopotential channel clips during movement and drifts at rest. Diagnose two distinct circuit/interface causes and propose a staged bench test before changing the electrode protocol.", rubric: ["Separates saturation/common-mode/range issue from baseline drift/polarization issue", "Uses a known differential/common-mode signal or electrode-equivalent network", "Checks gain, input range, bias return, filter cutoff, and recovery without a subject"] }),

  course("transport", "ENGR 250", "Thermodynamics & Transport in Bioengineering", "Bioengineering", "Year 3", 4, "Differential Equations; Physics: Mechanics; General Chemistry II", "Conservation laws, thermodynamic driving forces, fluid mechanics, heat and mass transfer, and scaling applied to cells, tissues, and bioprocess equipment.", ["Write control-volume balances for mass and energy.", "Apply diffusion and advection models with boundary conditions.", "Estimate flow regime and pressure drop.", "Use dimensional analysis to select dominant mechanisms."], ["transport", "engineeringMath"], ["biomedical", "tissue", "geroscience"], [
    lesson("Control volumes and conservation", ["Write accumulation = in − out + generation − consumption.", "Choose a control volume and distinguish steady from transient state."], "Conservation balances are the backbone of transport. For a species in a control volume, accumulation equals inflow minus outflow plus generation minus consumption. Steady state means accumulation is zero, not that fluxes vanish. Energy balances include heat, work, enthalpy flow, and kinetic or potential terms when relevant. The control volume and assumptions should be drawn before algebra; neglected terms should be justified by scale or operating regime.", "A well-mixed vessel of volume V with inflow Q and concentration Cin and equal outflow has V dC/dt=Q(Cin−C)−kVC for first-order consumption.", numeric("A reactor receives 2 L/min at 5 g/L and exits at the same flow. There is no reaction. At steady state, what is the outlet concentration in g/L?", 5, "g/L", "At steady state with no reaction, species inflow equals species outflow.", "The outlet concentration equals the inlet concentration, 5 g/L; the flow changes mass rate, not the steady concentration."), [["Control volume", "A defined region in space across whose boundary mass, energy, and momentum may flow."], ["Steady state", "A condition where stored quantities do not change with time, though through-flows can persist."]]),
    lesson("Diffusion, reaction, and characteristic length", ["Use Fick's law to determine flux direction and scale.", "Compare diffusion and reaction timescales."], "Fick's first law is J=−D∇C; flux points down the concentration gradient. A characteristic diffusion time is td≈L²/D, while a first-order reaction time is tr≈1/k. Their ratio defines a Damköhler-type comparison that indicates whether diffusion or reaction limits a process. Boundary conditions and geometry determine full solutions. In a thick construct, oxygen consumption can create a core deficit even if surface concentration is adequate.", "If D=2×10⁻⁹ m²/s and L=200 μm, td≈L²/D=20 s, before reaction or geometry corrections.", numeric("For D=1×10⁻⁹ m²/s and a characteristic length L=100 μm, estimate L²/D in seconds.", 10, "s", "Convert 100 μm to 1×10⁻⁴ m, then square and divide by D.", "(1×10⁻⁴ m)²/(1×10⁻⁹ m²/s)=10 s."), [["Fick's first law", "Diffusive flux is proportional to the negative concentration gradient, J=−D∇C."], ["Damköhler number", "A dimensionless comparison of reaction and transport timescales; convention depends on the process being modeled."]], "diffusion"),
    lesson("Fluid mechanics and microvascular flow", ["Compute Reynolds number and state its limits.", "Apply pressure-flow relations for idealized laminar conduits."], "The Reynolds number Re=ρUL/μ compares inertial and viscous effects. In microscale devices Re is often small, making viscous forces dominant, but transitions depend on geometry and entrance effects. Fully developed laminar flow in a circular tube follows Poiseuille's law; the r⁴ dependence makes flow highly sensitive to lumen size. Cells, non-Newtonian fluids, compliant walls, and branching networks violate simple assumptions and may require measured or numerical models.", "For water-like fluid with ρ=1000 kg/m³, U=1 mm/s, L=100 μm, and μ=10⁻³ Pa·s, Re=0.1.", numeric("A flow has ρ=1000 kg/m³, U=0.02 m/s, L=0.5 mm, and μ=0.001 Pa·s. What is Re?", 10, "", "Use Re=ρUL/μ and convert millimeters to meters.", "Re=1000×0.02×0.0005/0.001=10."), [["Reynolds number", "Dimensionless ratio of inertial to viscous effects, Re=ρUL/μ."], ["Poiseuille flow", "The ideal laminar pressure-driven flow of a Newtonian fluid through a straight circular tube."]]),
    lesson("Heat transfer and coupled transport", ["Compare conduction, convection, and radiation.", "Use a resistance network for heat or mass transfer."], "Heat can move by conduction, convection, and radiation; in aqueous biological systems, conduction and convection usually dominate at moderate scales. Fourier's law links heat flux to temperature gradient, while convective transfer scales with a heat-transfer coefficient and area. Thermal resistance networks can simplify layered constructs. Heat, solute, and charge transport share mathematical structures but have different constitutive coefficients and boundary conditions. Scaling identifies when a term can be neglected without implying it is universally unimportant.", "For a slab, conductive resistance is Rth=L/(kA); doubling thickness doubles resistance while doubling area halves it.", numeric("A slab has thickness 0.02 m, conductivity 0.5 W/(m·K), and area 0.10 m². What is its conductive thermal resistance in K/W?", 0.4, "K/W", "Use Rth=L/(kA).", "Rth=0.02/(0.5×0.10)=0.4 K/W."), [["Thermal conductivity", "A material coefficient relating conductive heat flux to temperature gradient."], ["Thermal resistance", "Temperature drop per heat-transfer rate for a specified geometry and boundary model."]]),
  ], { prompt: "A perfused construct has adequate inlet oxygen but a hypoxic center. Explain how flow, diffusion distance, and cellular consumption jointly determine the gradient; propose two design changes and one measurement that could falsify your model.", rubric: ["Connects advective delivery at channels to diffusion into tissue", "Relates diffusion length/time to consumption demand", "Suggests geometry/perfusion/cell-density changes and direct spatial oxygen measurement"] }),

  course("signals-control", "EE 310", "Signals, Systems & Feedback Control", "Electrical engineering", "Year 3", 4, "Differential Equations; Linear Algebra; Circuits recommended", "Continuous and discrete signals, linear systems, frequency response, feedback, stability, and controller design for sensors, actuators, and biological regulation.", ["Model systems with transfer functions or state space.", "Interpret poles, zeros, and frequency response.", "Evaluate closed-loop stability and tracking.", "Tune feedback with attention to noise, saturation, and uncertainty."], ["signals", "control"], ["biomedical", "robotics", "tissue"], [
    lesson("LTI systems, convolution, and transfer functions", ["Use impulse response to characterize an LTI system.", "Connect differential equations to transfer functions."], "A linear time-invariant system is characterized by its impulse response h(t); output is the convolution y=x*h. With zero initial conditions, Laplace transforms turn differential equations into algebraic transfer functions G(s)=Y(s)/U(s). Poles govern natural modes; zeros shape input-output cancellation and frequency response. Initial conditions and nonlinearities are excluded by the standard transfer-function model and must be handled separately when they matter.", "For τẏ+y=u, G(s)=1/(τs+1), a first-order low-pass with DC gain 1 and time constant τ.", choice("For G(s)=1/(s+4), where is the pole?", ["s=+4", "s=−4", "s=0", "There is no pole"], 1, "Set the denominator equal to zero.", "s+4=0 gives a pole at s=−4, corresponding to a decaying continuous-time mode."), [["Impulse response", "The output of an LTI system to a unit impulse; it determines all input-output behavior through convolution."], ["Pole", "A value of the transform variable where a system transfer function's denominator is zero."]]),
    lesson("Frequency response and filtering", ["Evaluate gain and phase at a sinusoidal frequency.", "Choose sampling and filtering parameters for a measured signal."], "For a stable LTI system, sinusoidal inputs produce sinusoidal steady-state outputs at the same frequency with changed gain and phase. Frequency response G(jω) supports filter and sensor design. Bandwidth describes the range over which a system meets a specified response criterion; it is not a single universal property without a criterion. Sampling must capture relevant dynamics, while anti-alias filters limit unresolved frequencies and sensor bandwidth constrains what can be measured.", "A first-order low-pass with τ=0.1 s has cutoff fc=1/(2πτ)≈1.59 Hz; signals far above this are attenuated.", numeric("A first-order low-pass has τ=0.05 s. Estimate its cutoff frequency in Hz.", 3.18, "Hz", "Use fc=1/(2πτ).", "fc=1/(2π×0.05)≈3.18 Hz.", 0.08), [["Bandwidth", "The frequency range over which performance meets a stated gain, phase, or error criterion."], ["Phase lag", "The phase delay of a system output relative to a sinusoidal input at a given frequency."]]),
    lesson("Feedback, stability, and robustness", ["Derive a closed-loop transfer function for unity feedback.", "Explain stability margins and model uncertainty."], "For a negative unity-feedback loop with forward transfer G, closed-loop response is T=G/(1+G). Stability depends on roots of the closed-loop characteristic equation, not merely on whether components are individually stable. Feedback can improve tracking and reject disturbances but can amplify measurement noise or destabilize a delayed plant. Robustness asks whether performance and stability persist under parameter uncertainty and unmodeled dynamics. Saturation and anti-windup matter in physical controllers.", "For proportional control of a unit-gain first-order plant, raising controller gain speeds tracking but also raises sensitivity to noise and unmodeled delay.", choice("In negative unity feedback, what is the closed-loop transfer function from reference to output?", ["G/(1−G)", "G/(1+G)", "1/G", "1+G"], 1, "Write the error as reference minus output and solve the loop equation.", "With y=Ge and e=r−y, y=G(r−y), so y/r=G/(1+G)."), [["Closed-loop transfer", "The input-output relationship after feedback is connected; for negative unity feedback it is G/(1+G)."], ["Robustness", "The ability to maintain acceptable stability and performance despite uncertainty and unmodeled effects."]]),
    lesson("Controller design and sampled implementation", ["Compare proportional, integral, and derivative actions.", "Account for discretization, sensor noise, and actuator saturation."], "Proportional action responds to present error, integral action accumulates past error to remove steady-state offset, and derivative action responds to error trend but amplifies high-frequency noise. PID tuning trades rise time, overshoot, steady-state accuracy, and robustness. Digital implementation introduces sample-and-hold behavior, computation delay, quantization, and derivative filtering. The tested controller should include actuator limits and anti-windup logic; a mathematically stable ideal design can fail on hardware.", "For a first-order thermal process, integral action can eliminate a persistent offset from heat loss, but too much integral gain can produce slow oscillation after saturation.", choice("Which PID term is most directly responsible for eliminating a constant steady-state error in many systems?", ["Proportional", "Integral", "Derivative", "Sampling"], 1, "A constant error accumulates over time in one of the terms.", "Integral action accumulates error, continuing to adjust the control input until a constant offset is removed, provided the loop is stable and not persistently saturated."), [["Integral windup", "Excessive accumulation of the integral controller state while an actuator is saturated."], ["Sample-and-hold", "A digital implementation that samples a signal and holds the value between updates."]]),
  ], { prompt: "A controller tracks a set point quickly but oscillates after a sensor filter is added. Explain the phase mechanism and outline a safe retuning sequence that preserves a measured stability margin.", rubric: ["Recognizes filter adds phase lag and changes loop crossover/margins", "Proposes reducing gain or redesigning bandwidth/lead compensation", "Requires step/frequency testing with saturation and disturbance monitoring before deployment"] }),

  course("robotics", "ME 320", "Robotics & Mechatronics", "Mechanical engineering", "Year 3", 4, "Linear Algebra; Differential Equations; Circuits recommended", "Frames, kinematics, dynamics, sensing, actuation, planning, and feedback combined in a biomedical or laboratory automation design workflow.", ["Transform coordinates between robot and task frames.", "Solve forward and inverse kinematics for a planar arm.", "Relate actuator torque, gearing, and load.", "Design a sensing and control loop with failure limits."], ["robotics", "signals", "numerical"], ["robotics", "biomedical"], [
    lesson("Frames, rotations, and homogeneous transforms", ["Compose planar rigid transforms in the correct order.", "Track coordinate-frame labels through a kinematic chain."], "A rigid transform combines rotation and translation. Homogeneous coordinates represent both as a 3×3 matrix in 2D or 4×4 in 3D, with frame conventions stated explicitly. Matrix multiplication is not commutative: transforming a point from tool to world is not interchangeable with world to tool. Rotation matrices should satisfy RᵀR=I and det(R)=+1. A frame diagram often catches errors before a numerical result does.", "Translate by (2,0) in world coordinates then rotate the frame by 90°; the outcome differs from rotating first then translating, unless the transform is expressed consistently.", numeric("A point at (1,0) is rotated 90° counterclockwise about the origin. What is its y-coordinate?", 1, "", "Apply the 2D rotation matrix to (1,0).", "The rotated point is (0,1), so y=1."), [["Homogeneous transform", "A matrix representation that combines rotation and translation for coordinate-frame mapping."], ["Kinematic chain", "A sequence of linked transforms from a robot base to an end effector."]]),
    lesson("Forward and inverse kinematics", ["Derive end-effector position for a two-link planar arm.", "Recognize singularities and multiple inverse solutions."], "Forward kinematics maps joint coordinates to end-effector pose. For a planar two-link arm, x=L₁cosθ₁+L₂cos(θ₁+θ₂), y=L₁sinθ₁+L₂sin(θ₁+θ₂). Inverse kinematics solves for joint values that reach a desired pose; multiple solutions or no solution may exist under joint and workspace constraints. The Jacobian maps joint velocity to end-effector velocity and loses rank at singular configurations.", "For equal links L and a straight arm, the reach is 2L; nearby desired points may correspond to elbow-up and elbow-down configurations.", numeric("A planar arm has two 0.5 m links and both joints at 0°. What is the end-effector x-position in meters?", 1, "m", "At 0° both links extend along +x, so add their lengths.", "x=0.5+0.5=1.0 m."), [["Forward kinematics", "Mapping from joint variables to the robot end-effector pose."], ["Singularity", "A configuration where the kinematic Jacobian loses rank and some end-effector motions require unbounded or unavailable joint velocities."]]),
    lesson("Robot dynamics, actuators, and energy", ["Estimate torque and power for a joint motion.", "Include gear ratio and efficiency with consistent conventions."], "Robot dynamics relate joint torques to acceleration, velocity, configuration, and external loads. A DC motor's torque and speed depend on current and back-emf; gearing trades speed for torque and adds inertia, backlash, and loss. Mechanical power is P=τω. Peak, continuous, and thermal ratings differ. Biomedical devices must also consider contact forces, fail-safe states, and biological variability rather than sizing only to nominal loads.", "A joint delivering 0.4 N·m at 5 rad/s outputs 2 W mechanical power before transmission losses.", numeric("A joint supplies 0.8 N·m at 3 rad/s. What is mechanical power in watts?", 2.4, "W", "Use P=τω.", "P=0.8×3=2.4 W."), [["Back-emf", "The voltage generated by a motor as it rotates, opposing applied voltage and relating speed to electrical behavior."], ["Backlash", "Lost motion caused by clearance between gear teeth or transmission components."]]),
    lesson("Planning, sensing, and closed-loop execution", ["Separate a plan from a feedback policy.", "Identify sensing uncertainty and safety constraints."], "A path plan specifies feasible motion through a modeled environment; feedback corrects deviations using sensor observations. Localization uncertainty, actuator limits, latency, and obstacle uncertainty affect execution. A robust system monitors safety constraints online and enters a defined safe state on sensor loss or collision. For lab automation, repeatability, contamination boundaries, calibration, and recovery after interrupted protocols are as important as nominal trajectory accuracy.", "A pipetting robot can have precise joint encoders but still miss a well if the plate frame is mislocalized; a fiducial or vision check closes that uncertainty.", choice("Why does feedback remain necessary after a collision-free path is planned?", ["The plan cannot account for every disturbance, calibration error, or state-estimation error", "Feedback makes geometry unnecessary", "A path plan determines actual forces exactly", "It is needed only to increase motor speed"], 0, "Execution occurs with real sensors, loads, and disturbances, not an exact mathematical model.", "A plan is based on estimated state and a model. Feedback uses new measurements to correct disturbances and estimation or actuation errors."), [["State estimation", "Inference of a system's internal state from sensor data and a model."], ["Safe state", "A defined system condition that minimizes risk after a fault or uncertainty threshold is reached."]]),
  ], { prompt: "A two-link arm reaches a target in simulation but stalls near full extension on hardware. Explain the Jacobian/dynamics issue, identify two measurements needed, and propose a safer task-space plan.", rubric: ["Identifies near-singular Jacobian and amplified joint velocity/torque demands", "Requests joint position/velocity/current or torque and calibration/load data", "Proposes avoiding the singular region, reducing speed, or using constrained redundancy with safety monitoring"] }),

  course("cellular-biomechanics", "BME 340", "Cellular Biomechanics & Mechanobiology", "Bioengineering", "Year 3", 3, "Cell biology; Physics: Mechanics; Differential Equations recommended", "Connect forces, matrix mechanics, cell adhesion, mechanotransduction, and quantitative assays across molecular-to-tissue scales.", ["Translate boundary conditions into stress and strain measures.", "Interpret viscoelastic and nonlinear material behavior.", "Connect integrin/cytoskeletal signaling to mechanical context.", "Design an experiment that separates stiffness from ligand density."], ["biomaterials", "transport"], ["biomedical", "tissue", "geroscience"], [
    lesson("Stress, strain, and constitutive behavior", ["Distinguish force, stress, displacement, and strain.", "Select a constitutive model appropriate to the time and strain regime."], "Stress is force per area and strain is normalized deformation; neither is a material property by itself. A constitutive law maps deformation history to stress. Linear elasticity is useful at small strain and specified directions, while viscoelastic models include time-dependent relaxation and creep. Biological tissues can be anisotropic, nonlinear, hydrated, and actively remodeled. Compare mechanical data only when geometry, loading mode, temperature, hydration, preconditioning, and strain rate are reported.", "A standard linear solid can relax toward a nonzero long-time modulus, unlike a Maxwell element that relaxes fully under an ideal step strain.", choice("Which test measures stress relaxation?", ["Apply a fixed strain and record stress versus time", "Apply a fixed stress and record strain versus time", "Hold both stress and strain at zero", "Measure only specimen mass"], 0, "Relaxation asks how force response changes while deformation is held fixed.", "Stress relaxation is measured by imposing a step or fixed strain and recording the time-dependent stress response."), [["Creep", "Time-dependent strain increase under a sustained applied stress."], ["Stress relaxation", "Time-dependent stress decrease under a sustained imposed strain."]]),
    lesson("Adhesion, cytoskeleton, and force transmission", ["Trace a force path from extracellular matrix to nucleus.", "Predict how adhesion geometry changes local signaling."], "Integrins bind extracellular matrix ligands and connect through focal-adhesion proteins to actin, myosin, and intracellular signaling pathways. Adhesion maturation, force loading, and cytoskeletal tension affect cell spreading and mechanosensitive signaling. Ligand identity and density, tether mobility, substrate stiffness, and topography can change independently, so experiments must avoid confounding them. Traction-force microscopy infers cellular forces from substrate deformation and requires a calibrated elastic model and regularized inverse solution.", "A stiffer substrate can increase traction only under conditions where cells can engage and remodel adhesions; stiffness alone does not specify cell fate.", choice("In traction-force microscopy, cell force is inferred primarily from:", ["Substrate displacement and a mechanical model", "Cell color alone", "The number of microscope pixels", "The bulk media pH"], 0, "The method observes a deformation field and solves an inverse mechanics problem.", "Substrate displacements are converted to traction stresses using the substrate's calibrated mechanical properties and a suitable inverse model."), [["Focal adhesion", "A dynamic protein assembly linking integrins to the actin cytoskeleton and signaling machinery."], ["Traction-force microscopy", "An imaging method that estimates cell-generated forces from substrate deformation."]]),
    lesson("Mechanotransduction and mechanosensitive pathways", ["Distinguish a mechanical input from a molecular readout.", "Use perturbation and rescue to support a pathway mechanism."], "Mechanotransduction converts forces or deformation into biochemical signals through channels, adhesion complexes, cytoskeletal tension, and nuclear processes. A pathway marker changing with stiffness is correlation unless a perturbation tests necessity or sufficiency. Use orthogonal readouts, time courses, matched ligand presentation, and cell-state controls. Mechanistic claims should identify the applied stimulus, transmitted force, molecular sensor, intermediate signal, and functional outcome, while recognizing parallel pathways and adaptation.", "If inhibiting a mechanosensitive channel blocks calcium entry and a downstream transcriptional response, channel-specific rescue or an orthogonal perturbation strengthens the causal chain.", choice("A transcription factor enters nuclei on a stiff gel. Which next experiment best tests whether the factor is required for the downstream phenotype?", ["Knock down the factor and quantify phenotype with a rescue condition", "Increase gel stiffness again", "Measure the factor's mRNA once", "Replace the microscope objective"], 0, "Test necessity with a targeted perturbation and evaluate whether specific restoration rescues function.", "Loss-of-function followed by a specific rescue tests necessity and helps distinguish an off-target effect from a causal role."), [["Mechanotransduction", "Conversion of mechanical cues into biochemical or gene-regulatory responses."], ["Necessity test", "A perturbation showing that a component is required for an outcome under specified conditions."]]),
    lesson("Experimental design for cell mechanics", ["Separate matrix mechanics from ligand presentation and geometry.", "Choose analysis that respects nested replicates and batch structure."], "Hydrogels can vary in stiffness, ligand coupling, swelling, pore size, and viscoelastic relaxation. A mechanobiology design should measure the material actually experienced by cells and include a factorial or otherwise controlled strategy for covarying inputs. Donor, passage, seeding density, and batch can create nested variability. Predefine the primary endpoint, include positive and negative controls, and image fields using blinded selection. Report effect size and uncertainty, not only representative images.", "A 2×2 stiffness-by-ligand-density design estimates both main effects and interaction, provided each combination is independently fabricated and randomized across runs.", choice("Why include both low and high ligand density at each of two gel stiffnesses?", ["To estimate stiffness, ligand-density, and interaction effects separately", "To guarantee every cell has identical behavior", "To remove the need for biological replicates", "To make calibration unnecessary"], 0, "Crossing the factors prevents one experimental variable from standing in for the other.", "A factorial design varies stiffness and ligand density independently, allowing estimation of their main effects and interaction."), [["Factorial design", "A design that crosses levels of multiple factors to estimate main effects and interactions."], ["Biological replicate", "An independent biological unit, such as a donor or independently cultured sample, relevant to the inference."]]),
  ], { prompt: "A stiff hydrogel increases a differentiation marker, but stiffness was raised by increasing crosslinker that also reduced ligand mobility. Describe a redesigned experiment and one material characterization needed before interpreting the cell result.", rubric: ["Vary stiffness and ligand mobility/density independently or use orthogonal chemistry", "Characterize modulus and viscoelastic relaxation at culture conditions", "Includes matched ligand/adhesion controls and independent biological replicates"] }),

  course("biomaterials", "BME 350", "Biomaterials & Tissue Engineering", "Bioengineering", "Year 3", 4, "Cell biology; Organic Chemistry I; Statics/Materials; Transport recommended", "Design and evaluate cell-material systems through degradation, protein adsorption, immune response, scaffold transport, and functional regeneration.", ["Relate material chemistry and architecture to biological response.", "Estimate scaffold transport and mechanical constraints.", "Compare scaffold, cell, and signal strategies for a tissue target.", "Interpret evidence across in-vitro and in-vivo models."], ["biomaterials", "tissueEngineering"], ["biomedical", "tissue", "geroscience"], [
    lesson("Material properties at the biological interface", ["Connect surface chemistry to protein adsorption and cell response.", "Distinguish bulk properties from surface properties."], "Biological fluids condition a material surface rapidly through adsorption of proteins, lipids, and ions. Cells therefore interact with a dynamic interfacial layer rather than a pristine polymer alone. Surface energy, charge, roughness, chemistry, and mechanics influence adsorption and adhesion, but their effects depend on the biological milieu. Characterize bulk and surface properties separately and test at relevant protein composition, flow, sterilization state, and timescale.", "A hydrophilic surface may resist some nonspecific adsorption, yet specific ligands can be introduced to promote controlled adhesion; protein amount alone does not report conformation or activity.", choice("Why can equal amounts of adsorbed protein produce different cell responses on two materials?", ["Adsorbed proteins can differ in conformation, orientation, or accessible binding sites", "Cells only sense bulk density", "Protein amount fixes protein activity", "Surface chemistry cannot affect cells"], 0, "Quantity is not the same as biological presentation.", "Surface chemistry can alter protein conformation, orientation, and epitope accessibility even when total adsorbed mass is similar."), [["Protein corona", "The layer of biomolecules adsorbed onto a material in a biological environment."], ["Surface characterization", "Measurement of near-surface chemistry, topography, charge, or energy rather than only bulk properties."]]),
    lesson("Scaffold architecture, degradation, and mechanics", ["Balance pore architecture with load-bearing and fabrication constraints.", "Model degradation as a time-varying material property."], "Scaffold design couples pore size, interconnectivity, surface area, degradation, and mechanical support. Higher porosity can improve transport and cell access but reduce stiffness and strength. Degradation products can change local pH or become toxic; degradation should be synchronized with tissue formation and load transfer. Characterize wet mechanics over time, not only dry initial values. A scaffold is a dynamic participant in remodeling, not an inert container.", "If scaffold stiffness falls faster than new matrix stiffness rises, total construct support can drop before regenerated tissue is load-bearing.", numeric("A scaffold loses 15% of its remaining mass each week under a simplified first-order model. If initial mass is 100 mg and the same fraction is lost each week, what mass remains after one week?", 85, "mg", "Multiply the initial mass by the fraction retained, 1−0.15.", "100 mg×0.85=85 mg. Repeated weekly fractional loss would compound as 100×0.85ⁿ."), [["Interconnectivity", "The extent to which pores form connected pathways for cell ingress and transport."], ["Load transfer", "The changing share of mechanical support carried by scaffold and newly formed tissue."]]),
    lesson("Cells, signals, and tissue-specific strategies", ["Compare autologous, allogeneic, and progenitor-cell tradeoffs.", "Map cells, scaffold, biochemical cues, and mechanical conditions to a tissue goal."], "Tissue engineering typically combines cells, scaffolds, signaling cues, and a culture or implantation environment. Cell source affects immune compatibility, expansion, potency, and donor variability. Growth factors and genes can be spatially or temporally delivered; sustained exposure is not always beneficial. Mechanical loading can promote maturation or damage depending on tissue and stage. A design rationale should connect each component to a measurable functional criterion rather than equating marker expression with tissue function.", "A cartilage construct should be evaluated for matrix composition, mechanical properties, integration, and load-bearing function, not only a single chondrogenic marker.", choice("Which evidence most directly supports functional cartilage regeneration?", ["A single chondrogenic transcript is elevated", "The construct bears relevant load, forms appropriate matrix, and integrates with host tissue", "The scaffold has a blue dye", "More cells were seeded initially"], 1, "Look for a functional outcome aligned with the target tissue.", "Functionally relevant mechanical performance, tissue composition, and integration collectively support regeneration more strongly than one marker alone."), [["Potency", "The demonstrated capacity of a cell product to produce a defined biological function under specified conditions."], ["Functional endpoint", "An outcome measuring a tissue or device performance relevant to the intended use."]]),
    lesson("Translation, biocompatibility, and failure analysis", ["Distinguish biocompatibility from an absence of any biological response.", "Use case studies to identify clinical failure modes."], "Biocompatibility is the ability of a material to perform with an appropriate host response for a specific application; it does not mean biologically inert. Inflammation, thrombosis, fibrosis, infection, wear, and mechanical mismatch are context-dependent risks. Translational evidence moves from material characterization through cell assays, animal models, manufacturing controls, and clinically meaningful endpoints. Sterilization, shelf life, batch consistency, and regulatory testing can change material performance and must be part of design control.", "A degradable implant can be biocompatible only when degradation rate, products, local tissue response, and intended function are evaluated together.", choice("What is the best definition of biocompatibility?", ["No immune cell ever contacts the material", "Appropriate material performance with a host response suited to the application", "The material never degrades", "The same response in every tissue"], 1, "Biological response is judged in the context of a specific use.", "Biocompatibility is application-specific: a material must perform with an appropriate host response for its intended purpose."), [["Biocompatibility", "Appropriate performance with an appropriate host response for a specific application."], ["Design control", "A documented process linking requirements, risks, verification, validation, and changes to a device or material."]]),
  ], { prompt: "A degradable vascular scaffold supports initial patency but later develops neointimal narrowing. Build a failure-analysis plan that separates mechanical collapse, degradation chemistry, and biological response, and name a functional endpoint.", rubric: ["Measures lumen/geometry and time-resolved mechanical support", "Characterizes degradation products and local chemistry", "Separates host-cell response with appropriate controls and reports flow/patency function"] }),

  course("geroscience", "BIO 360", "Geroscience & Regenerative Biology", "Life sciences", "Year 3", 3, "Cell biology; Genetics; Biochemistry; Biostatistics recommended", "Mechanisms linking aging biology to tissue resilience, damage response, senescence, stem-cell function, and regeneration—taught with evidence appraisal and translational caution.", ["Distinguish organismal aging mechanisms from correlates.", "Interpret senescence and stem-cell assays with controls.", "Evaluate causal evidence for an intervention.", "Separate lifespan, healthspan, and tissue-function endpoints."], ["biology", "molecular", "biochemistry"], ["geroscience", "tissue"], [
    lesson("Aging as a systems process", ["Compare damage, maintenance, and adaptation models.", "Distinguish biomarker change from improved function."], "Aging is heterogeneous across species, tissues, and individuals. Mechanistic frameworks include genomic instability, epigenetic change, altered proteostasis, mitochondrial dysfunction, senescence, stem-cell exhaustion, and dysregulated nutrient sensing; these interact rather than forming a single linear pathway. A biomarker may predict risk without being a causal driver or a valid surrogate endpoint. Study design should define age, sex, strain, environment, tissue, and functional outcome explicitly.", "A change in an epigenetic clock after intervention does not by itself show that tissue function or healthspan improved; both should be measured independently.", choice("An intervention shifts a molecular aging biomarker but does not improve tissue function. What is the strongest conclusion?", ["The intervention has proven rejuvenation", "The biomarker changed; functional benefit remains unestablished", "The biomarker must be invalid", "The study proves lifespan extension"], 1, "Keep the measured endpoint separate from outcomes that were not tested.", "Only the measured biomarker change is established. Functional, clinical, or lifespan benefits require their own evidence and appropriate design."), [["Healthspan", "The period of life spent in good functional health, defined by specified measures."], ["Surrogate endpoint", "A biomarker intended to stand in for a clinical or functional outcome; it requires validation for that purpose."]]),
    lesson("Senescence, inflammation, and tissue context", ["Define senescence operationally using multiple features.", "Distinguish cell-state evidence from a single marker."], "Cellular senescence is a durable growth-arrest state associated with stress responses and context-dependent secretory programs. No single marker uniquely identifies senescent cells across tissues. Proliferation loss, p16/p21 pathways, DNA damage, lysosomal markers, morphology, and secreted factors should be combined with perturbation and time-course evidence. Senescence can suppress tumor formation or support wound repair, so removing cells may help or harm depending on timing, tissue, and intervention selectivity.", "A senescence-associated β-galactosidase-positive cell is not conclusive alone; a panel plus evidence of persistent arrest and appropriate controls is stronger.", choice("Why is one marker insufficient to identify senescent cells across tissues?", ["Markers can be shared with other stressed, differentiated, or lysosomal states", "Senescence has no measurable features", "Every tissue has identical cell composition", "A single marker proves causal function"], 0, "Biological states overlap in their observable features.", "Markers such as p16 or lysosomal activity can occur in other contexts and vary by tissue; a convergent panel and functional evidence are needed."), [["Cellular senescence", "A durable cell-cycle arrest state with context-dependent molecular and secretory features."], ["SASP", "Senescence-associated secretory phenotype; a variable set of secreted factors, not a universal fixed signature."]]),
    lesson("Stem cells, niches, and regenerative capacity", ["Relate stem-cell function to niche signals and tissue demand.", "Distinguish cell number from self-renewal and differentiation capacity."], "Stem-cell aging may involve intrinsic damage, altered epigenetic state, and changes in niche signals, immune environment, or systemic physiology. A larger stem-cell pool does not guarantee effective regeneration if function, engraftment, or lineage balance is impaired. Lineage tracing, clonal analysis, transplantation, and perturbation answer different questions and each introduces selection or context effects. Functional recovery should be measured at the tissue level as well as by cell markers.", "An expanded progenitor population after injury may reflect compensatory proliferation; it does not establish durable self-renewal or restoration of organ function.", choice("Which result most directly supports restored stem-cell self-renewal?", ["Transient increase in a proliferation marker", "Serial functional regeneration with lineage evidence and appropriate controls", "Higher total DNA content in bulk tissue", "One post-treatment image"], 1, "Self-renewal is a persistent functional property, not a snapshot count.", "Serial functional regeneration with lineage evidence tests sustained renewal and contribution more directly than a transient marker or bulk abundance."), [["Stem-cell niche", "The local and systemic environment that regulates stem-cell maintenance and function."], ["Lineage tracing", "A method that follows descendants of defined cells over time to infer contribution and fate."]]),
    lesson("Intervention evidence and translational design", ["Evaluate whether an intervention's mechanism is supported by its endpoints.", "Design a study that separates efficacy from toxicity or selection effects."], "Geroscience interventions may target nutrient sensing, senescence, inflammation, proteostasis, or tissue-specific repair. A successful model study needs randomization, blinding, dose and exposure data, sex-aware analysis, safety monitoring, and prespecified functional endpoints. Survival analyses require appropriate censoring and competing-risk considerations. Cross-species translation is uncertain because lifespan, immune biology, drug exposure, and disease burden differ. Mechanistic claims should be proportionate to causal evidence and replicated independently.", "If a senolytic improves function only in animals that tolerate a high dose, reporting survivors alone can exaggerate benefit; intent-to-treat and toxicity analyses are essential.", choice("Why report toxicity and all randomized animals alongside functional benefit?", ["To reveal selection and competing harms that can bias an efficacy estimate", "To guarantee the treatment works", "To increase the p-value", "Because randomization makes missing data irrelevant"], 0, "Treatment-related dropout can change who remains available for analysis.", "If toxicity changes survival or follow-up, survivor-only analysis can be biased. Accounting for all randomized animals and harms preserves a more complete treatment comparison."), [["Competing risk", "An event that prevents the outcome of interest from occurring or being observed, such as death before a functional endpoint."], ["Intent-to-treat", "Analysis that retains participants or experimental units in their assigned groups regardless of adherence, under a prespecified strategy."]]),
  ], { prompt: "A senolytic reduces marker-positive cells and improves grip strength in one mouse cohort but raises mortality in another strain. Outline a replication and mechanism study that could support or refute a tissue-specific benefit-risk claim.", rubric: ["Pre-specifies strain/sex/tissue strata and functional plus survival/toxicity endpoints", "Uses multiple senescence-state measures and cell-target engagement", "Includes randomized blinded replication, exposure/safety measures, and appropriate interaction analysis"] }),

  course("bioreactors", "BME 370", "Bioreactors & Tissue Culture Engineering", "Bioengineering", "Year 3", 3, "Cell biology; Statistics; Transport recommended", "Scale cell culture and tissue maturation through mass transfer, shear, process monitoring, control, sterility, and design-of-experiments principles.", ["Write a cell-culture mass balance.", "Estimate oxygen-transfer and shear constraints.", "Interpret growth kinetics and process data.", "Design controls and acceptance criteria for a reproducible process."], ["transport", "tissueEngineering"], ["tissue", "biomedical", "geroscience"], [
    lesson("Growth kinetics and process mass balance", ["Fit a simple exponential growth model over its valid phase.", "Calculate doubling time and identify when exponential assumptions fail."], "In a balanced exponential phase, dX/dt=μX and X(t)=X₀e^(μt). Doubling time td=ln2/μ. Real cultures transition through lag, exponential, nutrient-limited, and decline phases; density, media exchange, oxygen, and waste alter μ. A growth curve should report viable cell concentration, sampling plan, and passage context. A fitted rate from one interval is not a universal property of the cell line.", "If viable cell count rises from 0.5 to 2 million cells/mL over 48 h in log phase, μ=ln(4)/48=0.0289 h⁻¹ and doubling time is 24 h.", numeric("A culture doubles every 30 hours. What is its exponential growth rate μ in h⁻¹?", 0.0231, "h⁻¹", "Use μ=ln2/td and convert td to hours.", "μ=0.693/30=0.0231 h⁻¹.", 0.0005), [["Specific growth rate μ", "Fractional exponential increase in biomass or viable cell concentration per unit time."], ["Doubling time", "Time required for an exponentially growing population to double, td=ln2/μ."]]),
    lesson("Oxygen transfer and consumption", ["Apply an oxygen transfer balance.", "Compare oxygen transfer capacity to cellular demand."], "Dissolved oxygen is supplied by gas-liquid transfer and consumed by cells. A common model is OTR=kLa(C*−C), while oxygen uptake rate depends on viable cell density and specific consumption qO₂. Steady operation requires transfer capacity to meet demand at the target dissolved concentration. Increasing agitation or gas flow can raise kLa but also alter shear, bubbles, foam, and product quality. Measure oxygen where cells experience it, not only at a bulk probe.", "If kLa=20 h⁻¹, C*=0.20 mM, and C=0.05 mM, OTR=3 mM/h in the simplified bulk model.", numeric("A culture has 2×10⁶ cells/mL consuming 1×10⁻¹⁶ mol O₂/(cell·s). What is volumetric demand in mmol/(L·h)?", 0.72, "mmol/(L·h)", "Convert cells/mL to cells/L, then mol/s to mmol/h.", "2×10⁹ cells/L × 1×10⁻¹⁶ mol/(cell·s)=2×10⁻⁷ mol/(L·s). Multiply by 3600 and 1000 to get 0.72 mmol/(L·h).", 0.02), [["kLa", "The volumetric gas-liquid mass-transfer coefficient, combining interfacial area and liquid-film transfer."], ["Oxygen uptake rate", "The rate at which a cell population consumes oxygen per cell or per culture volume."]], "diffusion"),
    lesson("Mixing, shear, and scale-up", ["Estimate Reynolds number and mixing-time tradeoffs.", "Use dimensionless similarity only when the relevant constraints are preserved."], "Scale-up cannot preserve every variable at once. Reynolds number, power per volume, tip speed, mixing time, and gas-transfer capacity each capture different aspects of a reactor. Cells may be sensitive to local shear, bubble rupture, or repeated exposure to gradients. Geometric similarity alone does not guarantee equivalent physiology. Scale-down models can recreate large-scale gradients at tractable volume and help identify failure mechanisms before full scale-up.", "Maintaining constant tip speed while increasing impeller diameter changes rotational speed and may alter mixing and power density; the chosen criterion must match the process limitation.", choice("Why is constant tip speed alone insufficient to guarantee equivalent scale-up?", ["It does not preserve mixing, power input, oxygen transfer, and local stress simultaneously", "Tip speed has no units", "Cells cannot experience flow", "It always decreases vessel volume"], 0, "Scale-up objectives are coupled; one preserved variable does not fix all transport conditions.", "Equal tip speed does not ensure equal mixing time, power per volume, gas transfer, or local shear; the limiting process must be identified."), [["Power per volume", "Mechanical power input normalized by culture volume, often used as one scale-up criterion."], ["Scale-down model", "A smaller system designed to reproduce important gradients or stresses observed in a larger process."]]),
    lesson("Process monitoring, control, and quality", ["Choose critical process parameters and quality attributes.", "Separate process drift from assay variation."], "A reproducible culture process defines critical process parameters (CPPs) and critical quality attributes (CQAs), with sensors and sampling that can detect excursions. pH, dissolved oxygen, temperature, agitation, feed, viable cell density, and metabolite profiles may be monitored. Sensor calibration, sterile sampling, data integrity, and alarm response are part of the process. Acceptance criteria should be established from function and variability, not selected after seeing the batch results.", "A dissolved-oxygen probe that drifts low can trigger excessive agitation; a second calibrated measurement or reference check can distinguish sensor drift from true oxygen limitation.", choice("Which statement best distinguishes a process parameter from a quality attribute?", ["Agitation rate is a process parameter; potency is a product quality attribute", "Both are synonyms for cell count", "Potency is always an instrument setting", "A process parameter can never affect product quality"], 0, "One describes how the process is run; the other describes the resulting product or function.", "Agitation rate is a controlled process condition; potency is a measurable characteristic of the resulting cell or tissue product."), [["Critical process parameter", "A process variable whose variability can affect a critical quality attribute and therefore requires monitoring or control."], ["Critical quality attribute", "A measurable property that must remain within an appropriate limit or range to ensure product quality."]]),
  ], { prompt: "A scaled-up perfusion culture has normal bulk dissolved oxygen but a gradient in viability across the vessel. Propose a scale-down experiment and sampling plan that separates mixing limitation from cell-line instability.", rubric: ["Reproduces mixing/oxygen gradients at smaller scale and includes matched well-mixed control", "Samples spatially or temporally for oxygen, metabolites, and viability with calibrated methods", "Uses matched passage/seed bank and independent replicate cultures to test cell-line stability"] }),
];

export const courseById = Object.fromEntries(courses.map((item) => [item.id, item]));
export const allCards = courses.flatMap((item) => item.modules.flatMap((unit, unitIndex) => unit.cards.map((card, cardIndex) => ({
  id: `${item.id}-${unitIndex}-${cardIndex}`, courseId: item.id, courseCode: item.code, lessonTitle: unit.title, front: card[0], back: card[1],
}))));
